INSERT INTO exercises (external_id, name, name_fr, body_part, target_muscle, secondary_muscles, equipment, difficulty, instructions, gif_url, image_url, video_url) VALUES
('196HJGw','hip raise (bent knee)',NULL,'core','abs','{"glutes","hamstrings"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands by your sides, palms facing down.","Step:3 Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Step:4 Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/196HJGw.gif','https://static.exercisedb.dev/media/196HJGw.gif',NULL),
('1bQkKZK','smith bent knee good morning',NULL,'legs','glutes','{"hamstrings","lower back"}','machine',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart, toes pointing forward.","Step:2 Place the barbell across your upper back, resting it on your traps.","Step:3 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:4 Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Step:5 Engage your glutes and hamstrings to raise your torso back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1bQkKZK.gif','https://static.exercisedb.dev/media/1bQkKZK.gif',NULL),
('1cTf2Ux','ez bar standing french press',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.","Step:2 Raise the barbell above your head, fully extending your arms.","Step:3 Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Step:4 Pause for a moment, then extend your arms back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1cTf2Ux.gif','https://static.exercisedb.dev/media/1cTf2Ux.gif',NULL),
('1DN3iz4','smith upright row',NULL,'shoulders','delts','{"traps","biceps"}','machine',NULL,'{"Step:1 Stand with your feet shoulder-width apart, facing the smith machine.","Step:2 Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Keep your back straight and your core engaged.","Step:4 Pull the barbell up towards your chin, leading with your elbows.","Step:5 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1DN3iz4.gif','https://static.exercisedb.dev/media/1DN3iz4.gif',NULL),
('1g5bPpA','jack jump (male)',NULL,'cardio','cardiovascular system','{"quadriceps","calves"}','body weight',NULL,'{"Step:1 Stand with your feet together and your arms by your sides.","Step:2 Jump up, spreading your feet apart and raising your arms above your head.","Step:3 As you land, quickly jump back to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1g5bPpA.gif','https://static.exercisedb.dev/media/1g5bPpA.gif',NULL),
('1gFNTZV','barbell jump squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Step:2 Lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Once you reach the bottom of the squat, explode upwards by jumping off the ground.","Step:4 As you jump, extend your hips, knees, and ankles, pushing through your toes.","Step:5 Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."}','https://static.exercisedb.dev/media/1gFNTZV.gif','https://static.exercisedb.dev/media/1gFNTZV.gif',NULL),
('1GPHRyK','janda sit-up',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1GPHRyK.gif','https://static.exercisedb.dev/media/1GPHRyK.gif',NULL),
('1IFV9h3','push-up on lower arms - resistance variation',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Start in a plank position with your forearms on the ground and elbows directly below your shoulders.","Step:2 Engage your core and keep your body in a straight line from head to toe.","Step:3 Lower your chest towards the ground by bending your elbows, keeping them close to your body. Emphasize resistance control.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1IFV9h3.gif','https://static.exercisedb.dev/media/1IFV9h3.gif',NULL),
('1IG6gVF','prone twist on stability ball',NULL,'core','abs','{"obliques","lower back"}','other',NULL,'{"Step:1 Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.","Step:2 Place your hands behind your head or cross them over your chest.","Step:3 Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.","Step:4 Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.","Step:5 Pause for a moment, then return to the starting position.","Step:6 Repeat the rotation to the other side.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/1IG6gVF.gif','https://static.exercisedb.dev/media/1IG6gVF.gif',NULL),
('1jXLYEw','standing lateral stretch',NULL,'back','lats','{"shoulders","obliques"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Extend your arms straight out to the sides, parallel to the ground.","Step:3 Slowly lean your upper body to one side, feeling a stretch in your side and lats.","Step:4 Hold the stretch for 15-30 seconds.","Step:5 Return to the starting position and repeat on the other side.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1jXLYEw.gif','https://static.exercisedb.dev/media/1jXLYEw.gif',NULL),
('1kB3Wmk','dumbbell single leg calf raise',NULL,'legs','calves','{"ankles"}','dumbbell',NULL,'{"Step:1 Stand on the edge of a step or platform with your heels hanging off and your toes on the step.","Step:2 Hold a dumbbell in one hand and place your other hand on a wall or railing for support.","Step:3 Raise your heel as high as possible, lifting your body up onto your toes.","Step:4 Pause for a moment at the top, then slowly lower your heel back down below the step.","Step:5 Repeat for the desired number of repetitions, then switch to the other leg."}','https://static.exercisedb.dev/media/1kB3Wmk.gif','https://static.exercisedb.dev/media/1kB3Wmk.gif',NULL),
('1LVFcEn','calf stretch with rope',NULL,'legs','calves','{"hamstrings"}','other',NULL,'{"Step:1 Stand facing a wall or sturdy object with your feet hip-width apart.","Step:2 Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.","Step:3 Step back with your left foot, keeping your heel on the ground and your leg straight.","Step:4 Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.","Step:5 Hold the stretch for 20-30 seconds, then release.","Step:6 Repeat on the other leg."}','https://static.exercisedb.dev/media/1LVFcEn.gif','https://static.exercisedb.dev/media/1LVFcEn.gif',NULL),
('1oE78pm','core barbell upright row v. 2',NULL,'shoulders','delts','{"traps","biceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:2 Let the barbell hang in front of your thighs, arms fully extended. Perform with core intensity.","Step:3 Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Step:4 Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1oE78pm.gif','https://static.exercisedb.dev/media/1oE78pm.gif',NULL),
('1PK5Uo3','cable incline pushdown',NULL,'back','lats','{"triceps","shoulders"}','cable',NULL,'{"Step:1 Attach a straight bar to a high pulley cable machine.","Step:2 Stand facing away from the machine with your feet shoulder-width apart.","Step:3 Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:4 Lean forward slightly and keep your back straight.","Step:5 Pull the bar down towards your thighs by extending your elbows.","Step:6 Pause for a moment at the bottom, then slowly return the bar to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1PK5Uo3.gif','https://static.exercisedb.dev/media/1PK5Uo3.gif',NULL),
('1PLE8e9','dumbbell incline twisted flyes',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.","Step:2 Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.","Step:3 Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Step:4 As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.","Step:5 Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1PLE8e9.gif','https://static.exercisedb.dev/media/1PLE8e9.gif',NULL),
('1qrWgZ2','dumbbell decline hammer press',NULL,'chest','pectorals','{"triceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie on a decline bench with your feet secured and your head lower than your hips.","Step:2 Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Step:3 Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.","Step:4 Press the dumbbells back up to the starting position, fully extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1qrWgZ2.gif','https://static.exercisedb.dev/media/1qrWgZ2.gif',NULL),
('1RIkUHT','dumbbell iron cross - improved variation',NULL,'shoulders','delts','{"triceps","chest"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Step:2 Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body. Perform with improved intensity.","Step:3 Pause for a moment, then slowly lower your arms back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1RIkUHT.gif','https://static.exercisedb.dev/media/1RIkUHT.gif',NULL),
('1TkiAFK','dumbbell one arm shoulder press v. 2',NULL,'shoulders','delts','{"triceps","upper back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Step:2 Engage your core and press the dumbbell straight up overhead, fully extending your arm.","Step:3 Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.","Step:4 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/1TkiAFK.gif','https://static.exercisedb.dev/media/1TkiAFK.gif',NULL),
('1TVoin7','barbell lying triceps extension double',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Step:3 Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows. Focus on double movement.","Step:4 Pause for a moment at the bottom, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1TVoin7.gif','https://static.exercisedb.dev/media/1TVoin7.gif',NULL),
('1u36hhy','stability lever narrow grip seated row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and footrests to ensure proper form.","Step:2 Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Step:3 Grasp the handles with a narrow grip, palms facing each other.","Step:4 Keep your back straight and lean slightly forward.","Step:5 Pull the handles towards your torso, squeezing your shoulder blades together.","Step:6 Pause for a moment at the peak of the movement.","Step:7 Slowly release the handles and return to the starting position. Focus on stability movement.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1u36hhy.gif','https://static.exercisedb.dev/media/1u36hhy.gif',NULL),
('1V1gj1u','barbell seated close-grip concentration curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.","Step:2 Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.","Step:3 Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.","Step:4 Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1V1gj1u.gif','https://static.exercisedb.dev/media/1V1gj1u.gif',NULL),
('1VpF8db','dumbbell bicep curl lunge with bowling motion',NULL,'arms','biceps','{"forearms","shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Step:2 Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.","Step:3 As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.","Step:4 At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.","Step:5 Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.","Step:6 Repeat the lunge and curl motion, this time rotating your torso to the left.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/1VpF8db.gif','https://static.exercisedb.dev/media/1VpF8db.gif',NULL),
('1xHyxys','cable high pulley overhead tricep extension',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Attach a rope to a high pulley and stand facing away from the machine.","Step:2 Grasp the rope with both hands and extend your arms overhead.","Step:3 Keep your elbows close to your head and your upper arms stationary.","Step:4 Slowly lower the rope behind your head by bending your elbows.","Step:5 Pause for a moment, then extend your arms back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1xHyxys.gif','https://static.exercisedb.dev/media/1xHyxys.gif',NULL),
('1YB40kg','incline close-grip push-up',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Step:2 Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.","Step:3 Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/1YB40kg.gif','https://static.exercisedb.dev/media/1YB40kg.gif',NULL),
('1YUWDNZ','extended style inverted row',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Set up a bar at waist height or use a suspension trainer.","Step:2 Stand facing the bar or suspension trainer, with your feet shoulder-width apart.","Step:3 Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Lean back, keeping your body straight and your heels on the ground.","Step:5 Pull your chest towards the bar or handles, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower yourself back to the starting position.","Step:7 Repeat for the desired number of repetitions. Perform with extended intensity."}','https://static.exercisedb.dev/media/1YUWDNZ.gif','https://static.exercisedb.dev/media/1YUWDNZ.gif',NULL),
('1ZFqTDN','air bike',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your hands placed behind your head.","Step:2 Lift your legs off the ground and bend your knees at a 90-degree angle.","Step:3 Bring your right elbow towards your left knee while simultaneously straightening your right leg.","Step:4 Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.","Step:5 Continue alternating sides in a pedaling motion for the desired number of repetitions."}','https://static.exercisedb.dev/media/1ZFqTDN.gif','https://static.exercisedb.dev/media/1ZFqTDN.gif',NULL),
('225x2Vd','band kneeling twisting crunch',NULL,'core','abs','{"obliques"}','resistance band',NULL,'{"Step:1 Attach the band to a sturdy anchor point at waist height.","Step:2 Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.","Step:3 Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.","Step:4 Pause for a moment, then slowly return to the starting position.","Step:5 Repeat on the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/225x2Vd.gif','https://static.exercisedb.dev/media/225x2Vd.gif',NULL),
('25GPyDY','barbell curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.","Step:2 Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.","Step:3 Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale as you slowly begin to lower the bar back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/25GPyDY.gif','https://static.exercisedb.dev/media/25GPyDY.gif',NULL),
('27NNGFr','cable incline fly (on stability ball)',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Set up a stability ball at an incline angle.","Step:2 Attach the cable handles to the high pulleys of a cable machine.","Step:3 Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.","Step:4 Grasp the cable handles with an overhand grip, palms facing forward.","Step:5 Lean forward slightly, keeping your back straight and core engaged.","Step:6 With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.","Step:7 Continue the motion until your arms are parallel to the ground.","Step:8 Pause for a moment, then slowly return to the starting position.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/27NNGFr.gif','https://static.exercisedb.dev/media/27NNGFr.gif',NULL),
('2dImyQ8','dumbbell seated palms up wrist curl',NULL,'arms','forearms','{"biceps","shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Step:2 Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Step:3 Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Step:4 Pause for a moment, then lower your wrists back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2dImyQ8.gif','https://static.exercisedb.dev/media/2dImyQ8.gif',NULL),
('2Dk4xQV','rocking frog stretch',NULL,'legs','glutes','{"hamstrings","quadriceps"}','body weight',NULL,'{"Step:1 Start by kneeling on the ground with your knees hip-width apart.","Step:2 Place your hands on the ground in front of you for support.","Step:3 Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.","Step:4 Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.","Step:5 Hold this position for a few seconds, feeling a stretch in your glutes.","Step:6 Slowly return to the starting position by bending your knees and lowering your hips back down.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2Dk4xQV.gif','https://static.exercisedb.dev/media/2Dk4xQV.gif',NULL),
('2DxtqHL','barbell one arm side deadlift',NULL,'legs','glutes','{"hamstrings","quadriceps","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.","Step:2 Keep your back straight and your core engaged.","Step:3 Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.","Step:4 Lower the barbell as far as you can while maintaining good form.","Step:5 Pause for a moment, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/2DxtqHL.gif','https://static.exercisedb.dev/media/2DxtqHL.gif',NULL),
('2gPfomN','3/4 sit-up',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2gPfomN.gif','https://static.exercisedb.dev/media/2gPfomN.gif',NULL),
('2IHEa2T','barbell floor calf raise',NULL,'legs','calves','{"hamstrings"}','barbell',NULL,'{"Step:1 Place a barbell on the floor in front of you.","Step:2 Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.","Step:3 Hold onto a stable object for balance if needed.","Step:4 Raise your heels as high as possible, using your calves to lift your body.","Step:5 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2IHEa2T.gif','https://static.exercisedb.dev/media/2IHEa2T.gif',NULL),
('2IxROQ1','cable overhead triceps extension (rope attachment)',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Attach a rope to a cable machine at a high position.","Step:2 Stand facing away from the machine with your feet shoulder-width apart.","Step:3 Grasp the rope with both hands, palms facing each other, and bring your hands above your head.","Step:4 Keep your upper arms close to your head and your elbows pointing forward.","Step:5 Slowly lower the rope behind your head by bending your elbows.","Step:6 Pause for a moment, then extend your arms back up to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2IxROQ1.gif','https://static.exercisedb.dev/media/2IxROQ1.gif',NULL),
('2JCuFTU','dumbbell kneeling bicep curl exercise ball',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Kneel on the floor with an exercise ball in front of you.","Step:2 Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.","Step:3 Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Step:4 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2JCuFTU.gif','https://static.exercisedb.dev/media/2JCuFTU.gif',NULL),
('2jl9K55','spine twist',NULL,'core','abs','{"obliques","lower back"}','body weight',NULL,'{"Step:1 Sit on the ground with your legs extended in front of you.","Step:2 Bend your knees and place your feet flat on the ground, hip-width apart.","Step:3 Place your hands behind your head with your elbows pointing outwards.","Step:4 Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.","Step:5 Pause for a moment at the end of the twist, then slowly return to the starting position.","Step:6 Repeat the twist to the left side, bringing your left elbow towards your right knee.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/2jl9K55.gif','https://static.exercisedb.dev/media/2jl9K55.gif',NULL),
('2kattbR','ez barbell spider curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Step:2 Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Step:3 Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Inhale and slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2kattbR.gif','https://static.exercisedb.dev/media/2kattbR.gif',NULL),
('2KGnL6M','lever one arm shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back against the pad.","Step:2 Grasp the lever handle with one hand and position your elbow at a 90-degree angle.","Step:3 Press the lever upward until your arm is fully extended overhead.","Step:4 Pause for a moment at the top, then slowly lower the lever back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/2KGnL6M.gif','https://static.exercisedb.dev/media/2KGnL6M.gif',NULL),
('2kr2lWy','push-up (bosu ball)',NULL,'chest','pectorals','{"triceps","shoulders","core"}','other',NULL,'{"Step:1 Place the bosu ball on the ground with the flat side facing up.","Step:2 Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Step:3 Engage your core and lower your body down towards the bosu ball by bending your elbows.","Step:4 Push yourself back up to the starting position by extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2kr2lWy.gif','https://static.exercisedb.dev/media/2kr2lWy.gif',NULL),
('2LQkNPW','exercise ball hip flexor stretch',NULL,'legs','glutes','{"quadriceps","hamstrings"}','other',NULL,'{"Step:1 Place the stability ball on the ground and kneel in front of it.","Step:2 Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.","Step:3 Extend your left leg behind you, keeping it straight.","Step:4 Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.","Step:5 Hold the stretch for 20-30 seconds, then switch sides and repeat."}','https://static.exercisedb.dev/media/2LQkNPW.gif','https://static.exercisedb.dev/media/2LQkNPW.gif',NULL),
('2NImIAG','dumbbell bicep curl on exercise ball with leg raised',NULL,'arms','biceps','{"forearms","shoulders"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Step:3 Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.","Step:4 Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.","Step:5 While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.","Step:6 Repeat for the desired number of repetitions, then switch legs and repeat."}','https://static.exercisedb.dev/media/2NImIAG.gif','https://static.exercisedb.dev/media/2NImIAG.gif',NULL),
('2NpxjC1','dumbbell hammer curl v. 2',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your torso.","Step:2 Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","Step:3 This will be your starting position.","Step:4 Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:5 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:6 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:7 Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Step:8 Repeat for the recommended amount of repetitions."}','https://static.exercisedb.dev/media/2NpxjC1.gif','https://static.exercisedb.dev/media/2NpxjC1.gif',NULL),
('2ORFMoR','hack calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the sled machine to a comfortable weight.","Step:2 Stand on the sled machine with your toes on the platform and your heels hanging off.","Step:3 Hold onto the handles for stability.","Step:4 Raise your heels as high as possible by pushing through the balls of your feet.","Step:5 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2ORFMoR.gif','https://static.exercisedb.dev/media/2ORFMoR.gif',NULL),
('2Pya1cP','cable decline press',NULL,'chest','pectorals','{"triceps","shoulders"}','cable',NULL,'{"Step:1 Adjust the cable machine to a decline position.","Step:2 Sit on the decline bench facing the cable machine.","Step:3 Grasp the handles with an overhand grip and position them at chest level.","Step:4 Keep your feet flat on the ground and your back firmly against the bench.","Step:5 Exhale and push the handles away from your body, extending your arms fully.","Step:6 Pause for a moment at the end of the movement, squeezing your chest muscles.","Step:7 Inhale and slowly return the handles back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2Pya1cP.gif','https://static.exercisedb.dev/media/2Pya1cP.gif',NULL),
('2Qh2J1e','sled 45° leg press (side pov)',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Step:2 Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.","Step:3 Grip the handles on the sides of the seat for stability.","Step:4 Push against the footplate to extend your legs, straightening them completely.","Step:5 Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2Qh2J1e.gif','https://static.exercisedb.dev/media/2Qh2J1e.gif',NULL),
('2qTvJAZ','barbell standing back wrist curl',NULL,'arms','forearms','{"biceps","shoulders"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.","Step:2 Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.","Step:3 Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.","Step:4 Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2qTvJAZ.gif','https://static.exercisedb.dev/media/2qTvJAZ.gif',NULL),
('2Ryn564','assisted prone rectus femoris stretch',NULL,'core','abs','{"quadriceps"}','other',NULL,'{"Step:1 Lie face down on the ground with your legs straight.","Step:2 Bend your right knee and reach back with your right hand to grab your right foot or ankle.","Step:3 Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.","Step:4 Hold the stretch for 20-30 seconds.","Step:5 Release and repeat on the other side."}','https://static.exercisedb.dev/media/2Ryn564.gif','https://static.exercisedb.dev/media/2Ryn564.gif',NULL),
('2sQGZ5b','dumbbell one arm standing hammer curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your torso.","Step:2 Keep your elbows close to your torso and your upper arms stationary.","Step:3 Exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2sQGZ5b.gif','https://static.exercisedb.dev/media/2sQGZ5b.gif',NULL),
('2Ty4idJ','advanced dumbbell stiff leg deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Step:2 Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees. Focus on advanced movement.","Step:3 Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/2Ty4idJ.gif','https://static.exercisedb.dev/media/2Ty4idJ.gif',NULL),
('2zNKRUB','wrist circles',NULL,'arms','forearms','{"hands","wrists"}','body weight',NULL,'{"Step:1 Extend your arms straight out in front of you.","Step:2 Make a fist with both hands.","Step:3 Rotate your wrists in a circular motion, keeping your arms still.","Step:4 Continue the wrist circles for the desired number of repetitions."}','https://static.exercisedb.dev/media/2zNKRUB.gif','https://static.exercisedb.dev/media/2zNKRUB.gif',NULL),
('33AzZeV','barbell front raise and pullover',NULL,'chest','pectorals','{"deltoids","triceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Step:2 Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.","Step:3 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:4 Next, lower the barbell behind your head, keeping your arms straight.","Step:5 Pause for a moment at the bottom, then raise the barbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/33AzZeV.gif','https://static.exercisedb.dev/media/33AzZeV.gif',NULL),
('3d7wHyd','dumbbell bench seated press',NULL,'shoulders','delts','{"triceps","chest"}','dumbbell',NULL,'{"Step:1 Sit on a bench with a dumbbell in each hand, resting on your thighs.","Step:2 Lean back and position the dumbbells to the sides of your chest, palms facing forward.","Step:3 Press the dumbbells upward until your arms are fully extended.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3d7wHyd.gif','https://static.exercisedb.dev/media/3d7wHyd.gif',NULL),
('3eGE2JC','dumbbell front raise',NULL,'shoulders','delts','{"biceps","trapezius"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Step:2 Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Step:3 Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3eGE2JC.gif','https://static.exercisedb.dev/media/3eGE2JC.gif',NULL),
('3nvEbbF','cable twisting pull with intensified',NULL,'back','lats','{"shoulders","biceps"}','cable',NULL,'{"Step:1 Attach a cable handle to a low pulley and stand facing the machine.","Step:2 Grasp the handle with your left hand and step away from the machine, extending your arm fully.","Step:3 Position your feet shoulder-width apart, with your knees slightly bent.","Step:4 Keep your back straight and your core engaged throughout the exercise.","Step:5 Pull the handle towards your body, rotating your torso to the right as you do so.","Step:6 Squeeze your back muscles at the end of the movement.","Step:7 Slowly return to the starting position, keeping tension on the cable.","Step:8 (intensified variation) Repeat for the desired number of repetitions, then switch sides and perform with your right hand."}','https://static.exercisedb.dev/media/3nvEbbF.gif','https://static.exercisedb.dev/media/3nvEbbF.gif',NULL),
('3omWx6P','band alternating biceps curl',NULL,'arms','biceps','{"forearms"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.","Step:2 Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.","Step:3 Lower the arm back down to the starting position and repeat with the other arm.","Step:4 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/3omWx6P.gif','https://static.exercisedb.dev/media/3omWx6P.gif',NULL),
('3pqGMQj','band alternating v-up with simple',NULL,'core','abs','{"hip flexors"}','resistance band',NULL,'{"Step:1 Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Step:2 Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Step:3 As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other. Focus on simple movement.","Step:4 Repeat the movement, alternating the position of your legs with each repetition.","Step:5 Continue for the desired number of repetitions."}','https://static.exercisedb.dev/media/3pqGMQj.gif','https://static.exercisedb.dev/media/3pqGMQj.gif',NULL),
('3QgteDK','barbell wide reverse grip bench press horizontal',NULL,'chest','pectorals','{"triceps","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.","Step:3 Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Step:4 Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight. Focus on horizontal movement.","Step:5 Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3QgteDK.gif','https://static.exercisedb.dev/media/3QgteDK.gif',NULL),
('3s4NnTh','dumbbell standing biceps curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3s4NnTh.gif','https://static.exercisedb.dev/media/3s4NnTh.gif',NULL),
('3T12T87','dumbbell standing bent over two arm triceps extension',NULL,'arms','triceps','{"shoulders","back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Step:2 Bend forward at the waist, keeping your back straight and your knees slightly bent.","Step:3 Extend your arms straight back, keeping your elbows close to your body.","Step:4 Slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3T12T87.gif','https://static.exercisedb.dev/media/3T12T87.gif',NULL),
('3tAXPQ6','dumbbell over bench revers wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.","Step:2 Rest your forearms on the bench, allowing your wrists to hang off the edge.","Step:3 Slowly curl your wrists upward, bringing the dumbbells towards your body.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3tAXPQ6.gif','https://static.exercisedb.dev/media/3tAXPQ6.gif',NULL),
('3TZduzM','barbell incline bench press',NULL,'chest','pectorals','{"shoulders","triceps"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Lie down on the bench with your feet flat on the ground.","Step:3 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.","Step:5 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3TZduzM.gif','https://static.exercisedb.dev/media/3TZduzM.gif',NULL),
('3uj0Ozg','dynamic chest stretch (male)',NULL,'chest','pectorals','{"shoulders","triceps"}','body weight',NULL,'{"Step:1 Stand tall with your feet shoulder-width apart.","Step:2 Extend your arms straight out to the sides, parallel to the ground.","Step:3 Slowly bring your arms forward, crossing them in front of your body.","Step:4 Feel the stretch in your chest muscles.","Step:5 Hold the stretch for 10-30 seconds.","Step:6 Return to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3uj0Ozg.gif','https://static.exercisedb.dev/media/3uj0Ozg.gif',NULL),
('3XFdb1Z','cable squatting curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a cable handle to the lowest setting on a cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.","Step:4 Lower your body into a squat position, keeping your back straight and knees behind your toes.","Step:5 As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.","Step:6 Pause for a moment at the top of the curl, squeezing your biceps.","Step:7 Slowly lower the cable handle back to the starting position, fully extending your arms.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3XFdb1Z.gif','https://static.exercisedb.dev/media/3XFdb1Z.gif',NULL),
('3xK09Sk','bodyweight squatting row',NULL,'back','upper back','{"biceps","shoulders"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.","Step:2 Lower your body into a squat position, keeping your back straight and your knees behind your toes.","Step:3 From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.","Step:4 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3xK09Sk.gif','https://static.exercisedb.dev/media/3xK09Sk.gif',NULL),
('3ZflifB','cable pushdown',NULL,'arms','triceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a straight bar to a high pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Step:3 Grasp the bar with an overhand grip, hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary.","Step:5 Exhale and push the bar down until your elbows are fully extended.","Step:6 Pause for a moment, then inhale and slowly return the bar to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/3ZflifB.gif','https://static.exercisedb.dev/media/3ZflifB.gif',NULL),
('4c9BhzB','cable lateral pulldown with v-bar',NULL,'back','lats','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.","Step:2 Adjust the knee pad so that your thighs are secured under it.","Step:3 Keep your back straight and lean back slightly.","Step:4 Pull the v-bar down towards your upper chest while keeping your elbows close to your body.","Step:5 Squeeze your back muscles at the bottom of the movement.","Step:6 Slowly return the v-bar to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4c9BhzB.gif','https://static.exercisedb.dev/media/4c9BhzB.gif',NULL),
('4CBIBOM','barbell seated close grip behind neck triceps extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold the barbell with a close grip behind your neck, palms facing forward.","Step:3 Keep your elbows close to your head and slowly lower the barbell towards the back of your head.","Step:4 Pause for a moment, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4CBIBOM.gif','https://static.exercisedb.dev/media/4CBIBOM.gif',NULL),
('4cWjYEN','narrow push-up on exercise ball',NULL,'arms','triceps','{"chest","shoulders"}','other',NULL,'{"Step:1 Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.","Step:2 Engage your core and keep your body in a straight line from head to toe.","Step:3 Lower your chest towards the ball by bending your elbows, keeping them close to your body.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4cWjYEN.gif','https://static.exercisedb.dev/media/4cWjYEN.gif',NULL),
('4dF3maG','dumbbell one arm hammer preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.","Step:2 Hold the dumbbell with a neutral grip (palms facing your body).","Step:3 Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Inhale and slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/4dF3maG.gif','https://static.exercisedb.dev/media/4dF3maG.gif',NULL),
('4dUn2iv','barbell standing close grip curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.","Step:2 Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Step:3 Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale as you slowly begin to bring the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4dUn2iv.gif','https://static.exercisedb.dev/media/4dUn2iv.gif',NULL),
('4f8RXP8','cable standing row (v-bar)',NULL,'back','upper back','{"biceps","shoulders"}','cable',NULL,'{"Step:1 Stand facing the cable machine with your feet shoulder-width apart.","Step:2 Grasp the v-bar attachment with an overhand grip, palms facing down.","Step:3 Keep your back straight and your core engaged.","Step:4 Pull the v-bar towards your body, squeezing your shoulder blades together.","Step:5 Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4f8RXP8.gif','https://static.exercisedb.dev/media/4f8RXP8.gif',NULL),
('4GqRrAk','superman push-up',NULL,'chest','pectorals','{"core","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Step:2 Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","Step:3 As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.","Step:4 Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.","Step:5 Repeat the movement, this time lifting your left arm and right leg.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/4GqRrAk.gif','https://static.exercisedb.dev/media/4GqRrAk.gif',NULL),
('4H86mXM','sled 45 degrees one leg press pointed',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the sled machine to a 45-degree angle.","Step:2 Sit on the sled machine with your back against the pad and your feet on the footplate. Perform with pointed intensity.","Step:3 Place one foot on the footplate and extend your leg, pushing the sled away from you.","Step:4 Slowly bend your knee and lower the sled back to the starting position.","Step:5 Repeat with the other leg.","Step:6 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/4H86mXM.gif','https://static.exercisedb.dev/media/4H86mXM.gif',NULL),
('4hATdoB','cable rope one arm hammer preacher curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a rope handle to a low pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the rope handle with an underhand grip, palms facing up.","Step:4 Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.","Step:5 Keep your back straight and your core engaged throughout the exercise.","Step:6 Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.","Step:7 Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.","Step:8 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/4hATdoB.gif','https://static.exercisedb.dev/media/4hATdoB.gif',NULL),
('4ievMJ9','dumbbell seated bent over triceps extension',NULL,'arms','triceps','{"shoulders","back"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Step:2 Bend forward at the waist, keeping your back straight and your head up.","Step:3 Extend your arms straight back, keeping your elbows close to your head.","Step:4 Pause for a moment, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4ievMJ9.gif','https://static.exercisedb.dev/media/4ievMJ9.gif',NULL),
('4IKbhHV','alternate lateral pulldown',NULL,'back','lats','{"biceps","rhomboids"}','cable',NULL,'{"Step:1 Sit on the cable machine with your back straight and feet flat on the ground.","Step:2 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.","Step:4 Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4IKbhHV.gif','https://static.exercisedb.dev/media/4IKbhHV.gif',NULL),
('4Jc36XM','dumbbell over bench one arm reverse wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Step:2 Rest your forearm on the bench with your wrist hanging off the edge.","Step:3 Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/4Jc36XM.gif','https://static.exercisedb.dev/media/4Jc36XM.gif',NULL),
('4Jt8QsQ','push-up on lower arms',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Start in a plank position with your forearms on the ground and elbows directly below your shoulders.","Step:2 Engage your core and keep your body in a straight line from head to toe.","Step:3 Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4Jt8QsQ.gif','https://static.exercisedb.dev/media/4Jt8QsQ.gif',NULL),
('4KJEpzb','kettlebell bottoms up clean from the hang position',NULL,'arms','biceps','{"forearms","shoulders"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Step:3 Allow the kettlebell to hang down between your legs, with your arm fully extended.","Step:4 In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.","Step:5 As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.","Step:6 Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.","Step:7 Lower the kettlebell back down to the starting position by reversing the movement.","Step:8 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/4KJEpzb.gif','https://static.exercisedb.dev/media/4KJEpzb.gif',NULL),
('4Leypho','barbell skier',NULL,'shoulders','delts','{"triceps","core"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Step:3 Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.","Step:4 As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4Leypho.gif','https://static.exercisedb.dev/media/4Leypho.gif',NULL),
('4LIG9xr','barbell reverse preacher curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.","Step:2 Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Step:3 Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4LIG9xr.gif','https://static.exercisedb.dev/media/4LIG9xr.gif',NULL),
('4LoWllp','band fixed back close grip pulldown',NULL,'back','lats','{"biceps","forearms"}','resistance band',NULL,'{"Step:1 Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.","Step:2 Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.","Step:3 Grasp the band with a close grip, palms facing towards you.","Step:4 Keep your back straight and engage your core.","Step:5 Pull the band down towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Step:7 Slowly release the band back to the starting position, maintaining control throughout the movement.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4LoWllp.gif','https://static.exercisedb.dev/media/4LoWllp.gif',NULL),
('4Ml7QFO','hanging straight leg raise',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your legs up in front of you, keeping them straight.","Step:3 Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4Ml7QFO.gif','https://static.exercisedb.dev/media/4Ml7QFO.gif',NULL),
('4OaumBr','suspended row',NULL,'back','upper back','{"biceps","shoulders"}','body weight',NULL,'{"Step:1 Set up a suspension trainer at an appropriate height.","Step:2 Stand facing the anchor point with your feet shoulder-width apart.","Step:3 Hold the handles with an overhand grip, palms facing each other.","Step:4 Lean back, keeping your body straight and your heels on the ground.","Step:5 Pull your chest towards the handles, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower yourself back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4OaumBr.gif','https://static.exercisedb.dev/media/4OaumBr.gif',NULL),
('4QqYaJW','gentle prone twist on stability ball',NULL,'core','abs','{"obliques","lower back"}','other',NULL,'{"Step:1 Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.","Step:2 Place your hands behind your head or cross them over your chest.","Step:3 Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.","Step:4 Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.","Step:5 Pause for a moment, then return to the starting position.","Step:6 (gentle variation) Repeat the rotation to the other side.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/4QqYaJW.gif','https://static.exercisedb.dev/media/4QqYaJW.gif',NULL),
('4U7iLb5','lever pullover',NULL,'back','lats','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat and handles of the leverage machine to a comfortable position.","Step:2 Sit on the machine with your back against the pad and grasp the handles with an overhand grip.","Step:3 Keep your arms slightly bent and your core engaged.","Step:4 Slowly pull the handles towards your chest, squeezing your lats.","Step:5 Pause for a moment at the peak contraction, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4U7iLb5.gif','https://static.exercisedb.dev/media/4U7iLb5.gif',NULL),
('4x5Okof','resistance band seated chest press',NULL,'chest','pectorals','{"shoulders","triceps"}','resistance band',NULL,'{"Step:1 Sit on a chair or bench with your back straight and feet flat on the ground.","Step:2 Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.","Step:3 Extend your arms forward, pushing the resistance band away from your chest.","Step:4 Pause for a moment at the end of the movement, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/4x5Okof.gif','https://static.exercisedb.dev/media/4x5Okof.gif',NULL),
('50BETrz','biceps narrow pull-ups',NULL,'arms','biceps','{"forearms","shoulders"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Step:2 Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.","Step:3 Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/50BETrz.gif','https://static.exercisedb.dev/media/50BETrz.gif',NULL),
('53Ttlck','dumbbell lying rear lateral raise',NULL,'shoulders','delts','{"traps","rhomboids"}','dumbbell',NULL,'{"Step:1 Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.","Step:2 Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Step:3 Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/53Ttlck.gif','https://static.exercisedb.dev/media/53Ttlck.gif',NULL),
('58rdhvL','narrow style band jack knife sit-up',NULL,'core','abs','{"hip flexors"}','resistance band',NULL,'{"Step:1 Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Step:2 Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.","Step:3 Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Step:4 Repeat for the desired number of repetitions. Focus on narrow movement."}','https://static.exercisedb.dev/media/58rdhvL.gif','https://static.exercisedb.dev/media/58rdhvL.gif',NULL),
('5bpPTHv','kettlebell pistol squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Step:2 Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.","Step:3 Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.","Step:4 Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/5bpPTHv.gif','https://static.exercisedb.dev/media/5bpPTHv.gif',NULL),
('5BZHW9s','squat to overhead reach with twist',NULL,'legs','quads','{"glutes","hamstrings","core"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and toes slightly turned out.","Step:2 Lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 As you come up from the squat, raise your arms overhead and twist your torso to one side.","Step:4 Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.","Step:5 Continue alternating sides with each squat repetition."}','https://static.exercisedb.dev/media/5BZHW9s.gif','https://static.exercisedb.dev/media/5BZHW9s.gif',NULL),
('5eLRITT','dumbbell stiff leg deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Step:2 Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.","Step:3 Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/5eLRITT.gif','https://static.exercisedb.dev/media/5eLRITT.gif',NULL),
('5fKX7wi','dumbbell seated reverse grip one arm overhead tricep extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell with an underhand grip and extend your arm straight up overhead.","Step:3 Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Step:4 Pause for a moment, then extend your arm back up to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/5fKX7wi.gif','https://static.exercisedb.dev/media/5fKX7wi.gif',NULL),
('5ipN0iE','assisted pull-up inclined',NULL,'back','lats','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the machine to your desired weight and height settings.","Step:2 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Hang with your arms fully extended and your feet off the ground.","Step:4 Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.","Step:5 Continue pulling until your chin is above the handles.","Step:6 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:7 Repeat for the desired number of repetitions. Maintain inclined form throughout."}','https://static.exercisedb.dev/media/5ipN0iE.gif','https://static.exercisedb.dev/media/5ipN0iE.gif',NULL),
('5KLbZWx','kettlebell alternating press',NULL,'shoulders','delts','{"triceps","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Step:2 Press one kettlebell overhead, fully extending your arm.","Step:3 Lower the kettlebell back to shoulder height.","Step:4 Repeat with the other arm.","Step:5 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/5KLbZWx.gif','https://static.exercisedb.dev/media/5KLbZWx.gif',NULL),
('5lE7XRz','smith bent over row with declined',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Set up the smith machine with the bar at hip height.","Step:2 Stand facing the bar with your feet shoulder-width apart.","Step:3 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:4 Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:5 Pull the bar towards your lower chest, squeezing your shoulder blades together. Perform with declined intensity.","Step:6 Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/5lE7XRz.gif','https://static.exercisedb.dev/media/5lE7XRz.gif',NULL),
('5MRH8H2','ski step',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Bend your knees slightly and keep your back straight.","Step:3 Jump to the right, landing on your right foot while swinging your left leg behind your right leg.","Step:4 Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.","Step:5 Continue alternating jumps from side to side, mimicking a skiing motion.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/5MRH8H2.gif','https://static.exercisedb.dev/media/5MRH8H2.gif',NULL),
('5uFK1xr','barbell seated overhead triceps extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.","Step:3 Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.","Step:4 Pause for a moment, then extend your arms to raise the barbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/5uFK1xr.gif','https://static.exercisedb.dev/media/5uFK1xr.gif',NULL),
('5v7KYld','smith incline bench press',NULL,'chest','pectorals','{"shoulders","triceps"}','machine',NULL,'{"Step:1 Adjust the bench to a 30-45 degree incline.","Step:2 Sit on the bench with your back flat against the pad and feet firmly on the ground.","Step:3 Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.","Step:5 Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/5v7KYld.gif','https://static.exercisedb.dev/media/5v7KYld.gif',NULL),
('5VCj6iH','barbell hack squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and your toes slightly turned out.","Step:2 Hold the barbell behind your legs, resting it on your upper thighs.","Step:3 Lower your body by bending at the knees and hips, keeping your back straight and your chest up.","Step:4 Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Pause for a moment, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/5VCj6iH.gif','https://static.exercisedb.dev/media/5VCj6iH.gif',NULL),
('5vfAI0I','dumbbell scott press',NULL,'shoulders','delts','{"triceps","chest"}','dumbbell',NULL,'{"Step:1 Sit on a bench with a dumbbell in each hand, palms facing forward.","Step:2 Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Step:3 Press the dumbbells upward until your arms are fully extended.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/5vfAI0I.gif','https://static.exercisedb.dev/media/5vfAI0I.gif',NULL),
('5VXmnV5','bodyweight incline side plank',NULL,'core','abs','{"obliques","shoulders"}','body weight',NULL,'{"Step:1 Start by lying on your side with your legs extended and stacked on top of each other.","Step:2 Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Step:3 Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Step:4 Hold this position for the desired amount of time.","Step:5 Lower your hips back down to the ground and repeat on the other side."}','https://static.exercisedb.dev/media/5VXmnV5.gif','https://static.exercisedb.dev/media/5VXmnV5.gif',NULL),
('5WiFcYk','weighted lunge with swing',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a weight in each hand.","Step:2 Take a step forward with your right foot, lowering your body into a lunge position.","Step:3 As you lunge forward, swing the weights forward and upward, keeping your arms straight.","Step:4 Push off with your right foot and return to the starting position, swinging the weights back down.","Step:5 Repeat with your left foot and continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/5WiFcYk.gif','https://static.exercisedb.dev/media/5WiFcYk.gif',NULL),
('61GrD55','cable lying close-grip curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a straight bar to a low pulley cable machine.","Step:2 Lie face up on a flat bench with your feet flat on the ground.","Step:3 Grasp the bar with an underhand grip, hands shoulder-width apart.","Step:4 Extend your arms fully, keeping your elbows close to your sides.","Step:5 Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.","Step:6 Pause for a moment at the top, squeezing your biceps.","Step:7 Slowly lower the bar back to the starting position, fully extending your arms.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/61GrD55.gif','https://static.exercisedb.dev/media/61GrD55.gif',NULL),
('62Nw60O','barbell rear lunge v. 2',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Step:2 Take a step backward with your right foot, landing on the ball of your foot.","Step:3 Bend both knees to lower your body until your left thigh is parallel to the ground.","Step:4 Push through your left heel to return to the starting position.","Step:5 Repeat with the other leg."}','https://static.exercisedb.dev/media/62Nw60O.gif','https://static.exercisedb.dev/media/62Nw60O.gif',NULL),
('641mIfk','barbell incline reverse-grip press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Step:3 Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.","Step:4 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/641mIfk.gif','https://static.exercisedb.dev/media/641mIfk.gif',NULL),
('67n3r98','lever shoulder press',NULL,'shoulders','delts','{"triceps","chest"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back against the backrest.","Step:2 Grasp the handles with an overhand grip and position your hands at shoulder level.","Step:3 Push the handles upward until your arms are fully extended, but do not lock your elbows.","Step:4 Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/67n3r98.gif','https://static.exercisedb.dev/media/67n3r98.gif',NULL),
('6bOA1Oi','weighted side bend (on stability ball)',NULL,'core','abs','{"obliques","lower back"}','other',NULL,'{"Step:1 Sit on a stability ball with your feet shoulder-width apart and flat on the ground.","Step:2 Hold a weight in one hand and place your other hand on your hip.","Step:3 Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.","Step:4 Pause for a moment at the bottom, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/6bOA1Oi.gif','https://static.exercisedb.dev/media/6bOA1Oi.gif',NULL),
('6cKQC5E','dumbbell one arm upright row',NULL,'shoulders','delts','{"traps","biceps"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Step:2 Let the dumbbell hang at arm's length in front of your thighs, with your palm facing your body.","Step:3 Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.","Step:4 Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/6cKQC5E.gif','https://static.exercisedb.dev/media/6cKQC5E.gif',NULL),
('6CKUx7o','ez bar lying close grip triceps extension behind head',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.","Step:3 Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Step:4 Pause for a moment, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6CKUx7o.gif','https://static.exercisedb.dev/media/6CKUx7o.gif',NULL),
('6e2DcYX','dumbbell incline shoulder raise',NULL,'chest','serratus anterior','{"deltoids","trapezius"}','dumbbell',NULL,'{"Step:1 Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.","Step:2 Rest the dumbbells on your thighs and lean back onto the bench.","Step:3 Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.","Step:4 Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.","Step:5 Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6e2DcYX.gif','https://static.exercisedb.dev/media/6e2DcYX.gif',NULL),
('6em2Dxj','dumbbell alternate seated hammer curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.","Step:2 Keep your back straight and your elbows close to your torso.","Step:3 Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Step:4 Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Step:5 Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.","Step:6 Repeat the movement with your left arm.","Step:7 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/6em2Dxj.gif','https://static.exercisedb.dev/media/6em2Dxj.gif',NULL),
('6FMU51h','semi squat jump (male)',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Bend your knees and lower your body into a squat position.","Step:3 Jump explosively, extending your hips and knees while swinging your arms for momentum.","Step:4 Land softly on the balls of your feet and immediately go into the next repetition.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6FMU51h.gif','https://static.exercisedb.dev/media/6FMU51h.gif',NULL),
('6HiHHe0','barbell standing rocking leg calf raise',NULL,'legs','calves','{"hamstrings","quadriceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Step:2 Raise your heels off the ground as high as possible, balancing on the balls of your feet.","Step:3 Slowly lower your heels back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6HiHHe0.gif','https://static.exercisedb.dev/media/6HiHHe0.gif',NULL),
('6HmFgmx','standing calf raise (on a staircase)',NULL,'legs','calves','{"ankles","feet"}','body weight',NULL,'{"Step:1 Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.","Step:2 Hold onto a railing or wall for balance if needed.","Step:3 Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Step:4 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6HmFgmx.gif','https://static.exercisedb.dev/media/6HmFgmx.gif',NULL),
('6kSxYnw','barbell wrist curl v. 2',NULL,'arms','forearms','{"biceps","brachialis"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and your knees bent.","Step:2 Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Step:3 Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Step:4 Slowly curl your wrists upward, bringing the barbell towards your forearms.","Step:5 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6kSxYnw.gif','https://static.exercisedb.dev/media/6kSxYnw.gif',NULL),
('6MaEjVA','smith standing leg calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.","Step:2 Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.","Step:3 Place your hands on the bar for stability.","Step:4 Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.","Step:5 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6MaEjVA.gif','https://static.exercisedb.dev/media/6MaEjVA.gif',NULL),
('6MfS53i','dumbbell lying single extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.","Step:2 Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.","Step:3 Pause briefly at the bottom of the movement, then extend your arm back to the starting position.","Step:4 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/6MfS53i.gif','https://static.exercisedb.dev/media/6MfS53i.gif',NULL),
('6pTkI99','dumbbell one arm snatch',NULL,'legs','glutes','{"hamstrings","quadriceps","core"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Step:3 Lower the dumbbell towards the ground, keeping it close to your body.","Step:4 Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.","Step:5 As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.","Step:6 Catch the dumbbell overhead with a slight bend in your knees and hips.","Step:7 Lower the dumbbell back down to the starting position in a controlled manner.","Step:8 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/6pTkI99.gif','https://static.exercisedb.dev/media/6pTkI99.gif',NULL),
('6sMAmNv','dumbbell reverse spider curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6sMAmNv.gif','https://static.exercisedb.dev/media/6sMAmNv.gif',NULL),
('6sYyrRX','bent knee lying twist (male)',NULL,'legs','glutes','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Extend your arms out to the sides, perpendicular to your body.","Step:3 Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.","Step:4 Pause for a moment, then engage your core and slowly lift your knees back to the starting position.","Step:5 Repeat the movement to the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/6sYyrRX.gif','https://static.exercisedb.dev/media/6sYyrRX.gif',NULL),
('6t00BsF','cable one arm incline press on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','cable',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.","Step:2 Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.","Step:3 Press the cable handle forward and upward, extending your arm fully.","Step:4 Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/6t00BsF.gif','https://static.exercisedb.dev/media/6t00BsF.gif',NULL),
('6TG6x2w','ez barbell curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Step:2 Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Step:3 Exhale as you curl the barbell up towards your shoulders, contracting your biceps.","Step:4 Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6TG6x2w.gif','https://static.exercisedb.dev/media/6TG6x2w.gif',NULL),
('6vcvsLS','hanging straight leg raise with elevated',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your legs up in front of you, keeping them straight.","Step:3 Continue lifting until your legs are parallel to the ground or as high as you can comfortably go. Maintain elevated form throughout.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6vcvsLS.gif','https://static.exercisedb.dev/media/6vcvsLS.gif',NULL),
('6Wr0F3W','rounded twisted leg raise (female)',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended and your arms by your sides.","Step:2 Bend your knees and lift your legs off the ground, bringing them towards your chest. Emphasize rounded control.","Step:3 As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat the movement, this time twisting your hips to the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/6Wr0F3W.gif','https://static.exercisedb.dev/media/6Wr0F3W.gif',NULL),
('6YUfHPL','quads',NULL,'legs','quads','{"hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Step:3 Keep your chest up and your back straight.","Step:4 Lower yourself until your thighs are parallel to the ground.","Step:5 Push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6YUfHPL.gif','https://static.exercisedb.dev/media/6YUfHPL.gif',NULL),
('6ZCiYWQ','sit-up with arms on chest',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Cross your arms over your chest.","Step:3 Engaging your abs, lift your upper body off the ground towards your knees.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/6ZCiYWQ.gif','https://static.exercisedb.dev/media/6ZCiYWQ.gif',NULL),
('72BC5Za','archer pull up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Step:2 Engage your core and pull your shoulder blades down and back.","Step:3 As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.","Step:4 Continue pulling until your chin is above the bar and your bent arm is fully flexed.","Step:5 Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.","Step:6 Alternate sides with each repetition."}','https://static.exercisedb.dev/media/72BC5Za.gif','https://static.exercisedb.dev/media/72BC5Za.gif',NULL),
('75Bgtjy','potty squat',NULL,'core','abs','{"quadriceps","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes pointing slightly outward.","Step:2 Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.","Step:3 Keep your chest up and your back straight throughout the movement.","Step:4 Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.","Step:5 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/75Bgtjy.gif','https://static.exercisedb.dev/media/75Bgtjy.gif',NULL),
('76vfTdU','dumbbell step up single leg balance with bicep curl',NULL,'arms','biceps','{"quadriceps","glutes","hamstrings"}','dumbbell',NULL,'{"Step:1 Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.","Step:2 Place your right foot on the step, ensuring your entire foot is in contact with the surface.","Step:3 Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.","Step:4 At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.","Step:5 Lower the dumbbells back down and simultaneously lower your left foot back to the ground.","Step:6 Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/76vfTdU.gif','https://static.exercisedb.dev/media/76vfTdU.gif',NULL),
('7858za8','fluid dumbbell step-up lunge',NULL,'legs','quads','{"glutes","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.","Step:2 Place your right foot on the step, ensuring your entire foot is on the surface.","Step:3 Push through your right heel and lift your body up onto the step, bringing your left foot up as well.","Step:4 (fluid variation) Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.","Step:5 Repeat the movement, alternating which foot you step up with each time.","Step:6 Continue for the desired number of repetitions."}','https://static.exercisedb.dev/media/7858za8.gif','https://static.exercisedb.dev/media/7858za8.gif',NULL),
('78VqWQK','smith incline reverse-grip press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat of the smith machine to a comfortable incline angle.","Step:2 Sit on the machine with your back against the pad and your feet flat on the ground.","Step:3 Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.","Step:4 Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.","Step:5 Pause for a moment when the bar is just above your chest.","Step:6 Push the bar back up to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/78VqWQK.gif','https://static.exercisedb.dev/media/78VqWQK.gif',NULL),
('79AmJsI','dumbbell hammer curl with traditional',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your torso.","Step:2 Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","Step:3 This will be your starting position.","Step:4 Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:5 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:6 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:7 Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Step:8 Repeat for the recommended amount of repetitions. Focus on traditional movement."}','https://static.exercisedb.dev/media/79AmJsI.gif','https://static.exercisedb.dev/media/79AmJsI.gif',NULL),
('7AnZtSv','dumbbell over bench one arm wrist curl - strength variation',NULL,'arms','forearms','{"biceps","shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Step:2 Rest your forearm on the bench with your wrist hanging off the edge.","Step:3 Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position. Maintain strength form throughout.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/7AnZtSv.gif','https://static.exercisedb.dev/media/7AnZtSv.gif',NULL),
('7aolH9D','medicine ball chest push multiple response',NULL,'chest','pectorals','{"triceps","shoulders"}','medicine ball',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Step:2 Extend your arms forward, pushing the medicine ball away from your chest.","Step:3 Pause for a moment, then slowly bring the medicine ball back to your chest.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7aolH9D.gif','https://static.exercisedb.dev/media/7aolH9D.gif',NULL),
('7aVz15j','triceps dips floor',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.","Step:2 Slide your butt off the front of the chair with your legs extended in front of you.","Step:3 Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.","Step:4 Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.","Step:5 Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7aVz15j.gif','https://static.exercisedb.dev/media/7aVz15j.gif',NULL),
('7B4F5nZ','lever calf press',NULL,'legs','calves','{"hamstrings"}','machine',NULL,'{"Step:1 Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.","Step:2 Place your toes on the lever pad, with your heels hanging off the edge.","Step:3 Grasp the handles or side supports for stability.","Step:4 Push the lever pad down by extending your ankles, contracting your calf muscles.","Step:5 Pause for a moment at the bottom of the movement.","Step:6 Slowly return to the starting position by allowing your heels to rise back up.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7B4F5nZ.gif','https://static.exercisedb.dev/media/7B4F5nZ.gif',NULL),
('7Ba7bQ2','kettlebell two arm clean',NULL,'shoulders','delts','{"traps","forearms"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.","Step:2 Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Step:3 Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.","Step:4 As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.","Step:5 Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7Ba7bQ2.gif','https://static.exercisedb.dev/media/7Ba7bQ2.gif',NULL),
('7D5bgLT','dumbbell seated preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a preacher curl bench with your feet flat on the floor.","Step:2 Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.","Step:3 Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Step:4 Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/7D5bgLT.gif','https://static.exercisedb.dev/media/7D5bgLT.gif',NULL),
('7E06s6d','chest tap push-up (male)',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Step:2 Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Step:3 As you lower yourself, tap your chest with your right hand.","Step:4 Push yourself back up to the starting position.","Step:5 Repeat the movement, this time tapping your chest with your left hand.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/7E06s6d.gif','https://static.exercisedb.dev/media/7E06s6d.gif',NULL),
('7ePTw4B','exercise ball seated triceps stretch',NULL,'arms','triceps','{"shoulders"}','other',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand and extend your arm straight up above your head.","Step:3 Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.","Step:4 Hold the stretch for a few seconds, then return to the starting position.","Step:5 Repeat with the other arm."}','https://static.exercisedb.dev/media/7ePTw4B.gif','https://static.exercisedb.dev/media/7ePTw4B.gif',NULL),
('7F1DVzn','lever front pulldown',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Step:2 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.","Step:4 Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7F1DVzn.gif','https://static.exercisedb.dev/media/7F1DVzn.gif',NULL),
('7f2jsqP','dumbbell seated one arm rotate',NULL,'arms','forearms','{"shoulders","biceps"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.","Step:2 Raise the dumbbell up to shoulder height, keeping your elbow close to your body.","Step:3 Rotate your forearm outward, away from your body, while keeping your upper arm stationary.","Step:4 Pause for a moment at the top, then slowly rotate your forearm back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/7f2jsqP.gif','https://static.exercisedb.dev/media/7f2jsqP.gif',NULL),
('7gdLIXa','dumbbell lying hammer press',NULL,'chest','pectorals','{"triceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.","Step:2 Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Step:3 Press the dumbbells back up to the starting position, fully extending your arms.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7gdLIXa.gif','https://static.exercisedb.dev/media/7gdLIXa.gif',NULL),
('7HcfMBP','assisted standing triceps extension (with towel)',NULL,'arms','triceps','{"shoulders"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.","Step:2 Keep your elbows close to your ears and your upper arms stationary.","Step:3 Slowly extend your forearms upward, squeezing your triceps at the top.","Step:4 Pause for a moment, then slowly lower the towel back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7HcfMBP.gif','https://static.exercisedb.dev/media/7HcfMBP.gif',NULL),
('7Hg55JG','dumbbell clean',NULL,'legs','glutes','{"hamstrings","quadriceps","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Step:2 Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Step:3 Explosively extend your hips and knees, driving through your heels to jump off the ground.","Step:4 As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.","Step:5 Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.","Step:6 Lower the dumbbells back down to the starting position by reversing the movement.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7Hg55JG.gif','https://static.exercisedb.dev/media/7Hg55JG.gif',NULL),
('7i4msxz','cocoons with mega',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions. Emphasize mega control."}','https://static.exercisedb.dev/media/7i4msxz.gif','https://static.exercisedb.dev/media/7i4msxz.gif',NULL),
('7I6LNUG','lever seated row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and footrests to a comfortable position.","Step:2 Sit on the machine with your chest against the pad and your feet on the footrests.","Step:3 Grasp the handles with an overhand grip, shoulder-width apart.","Step:4 Keep your back straight and your core engaged.","Step:5 Pull the handles towards your body, squeezing your shoulder blades together.","Step:6 Pause for a moment at the peak of the movement.","Step:7 Slowly release the handles and return to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7I6LNUG.gif','https://static.exercisedb.dev/media/7I6LNUG.gif',NULL),
('7inpWch','dumbbell standing concentration curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.","Step:2 Place your opposite hand on your thigh for support.","Step:3 Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Step:4 Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly lower the dumbbell back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/7inpWch.gif','https://static.exercisedb.dev/media/7inpWch.gif',NULL),
('7jGOBF3','dumbbell close grip press',NULL,'arms','triceps','{"chest","shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Step:2 Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Step:3 Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Step:4 As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","Step:5 As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.","Step:6 After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."}','https://static.exercisedb.dev/media/7jGOBF3.gif','https://static.exercisedb.dev/media/7jGOBF3.gif',NULL),
('7M66AVi','barbell rollerout',NULL,'core','abs','{"lower back"}','barbell',NULL,'{"Step:1 Kneel on the floor and hold a barbell with both hands, shoulder-width apart.","Step:2 Roll the barbell forward, extending your arms and keeping your core engaged.","Step:3 Continue rolling forward until your body is fully extended and your arms are overhead.","Step:4 Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7M66AVi.gif','https://static.exercisedb.dev/media/7M66AVi.gif',NULL),
('7OeHptV','assisted standing chin-up',NULL,'back','lats','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the machine to your desired assistance level.","Step:2 Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Keep your chest up and shoulders back, engage your core, and slightly bend your knees.","Step:4 Pull your body up by flexing your elbows and driving your elbows down towards your sides.","Step:5 Continue pulling until your chin is above the bar.","Step:6 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7OeHptV.gif','https://static.exercisedb.dev/media/7OeHptV.gif',NULL),
('7R4NIjL','assisted standing triceps extension (with towel) with horizontal',NULL,'arms','triceps','{"shoulders"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.","Step:2 Keep your elbows close to your ears and your upper arms stationary.","Step:3 (horizontal variation) Slowly extend your forearms upward, squeezing your triceps at the top.","Step:4 Pause for a moment, then slowly lower the towel back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7R4NIjL.gif','https://static.exercisedb.dev/media/7R4NIjL.gif',NULL),
('7RWNjiB','dumbbell lying pronation on floor',NULL,'arms','forearms','{"biceps","triceps"}','dumbbell',NULL,'{"Step:1 Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.","Step:2 Rotate your palms so they are facing down towards the floor.","Step:3 Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.","Step:4 Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold for a moment, then slowly lower the dumbbells back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7RWNjiB.gif','https://static.exercisedb.dev/media/7RWNjiB.gif',NULL),
('7saC5zz','cable decline fly',NULL,'chest','pectorals','{"shoulders","triceps"}','cable',NULL,'{"Step:1 Adjust the cable machine to a decline position.","Step:2 Stand facing away from the machine with your feet shoulder-width apart.","Step:3 Hold the handles with your palms facing forward and your arms extended straight out in front of you.","Step:4 Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Step:5 Pause for a moment at the fully extended position, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7saC5zz.gif','https://static.exercisedb.dev/media/7saC5zz.gif',NULL),
('7uFJuXp','weighted kneeling step with swing',NULL,'shoulders','delts','{"triceps","core"}','other',NULL,'{"Step:1 Start in a kneeling position with your knees hip-width apart and your back straight.","Step:2 Hold a weight in each hand, with your arms extended straight down in front of you.","Step:3 Engage your core and swing the weights up and overhead, keeping your arms straight.","Step:4 Lower the weights back down to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7uFJuXp.gif','https://static.exercisedb.dev/media/7uFJuXp.gif',NULL),
('7vG5o25','dumbbell incline row',NULL,'back','upper back','{"biceps","shoulders"}','dumbbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Grab a dumbbell in each hand and sit on the bench with your chest against the incline.","Step:3 Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.","Step:4 Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7vG5o25.gif','https://static.exercisedb.dev/media/7vG5o25.gif',NULL),
('7w6i0vE','kettlebell alternating press on floor',NULL,'chest','pectorals','{"shoulders","triceps"}','kettlebell',NULL,'{"Step:1 Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Step:2 Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.","Step:3 Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.","Step:4 Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.","Step:5 Continue alternating the press motion with each kettlebell for the desired number of repetitions."}','https://static.exercisedb.dev/media/7w6i0vE.gif','https://static.exercisedb.dev/media/7w6i0vE.gif',NULL),
('7WaDzyL','side hip abduction',NULL,'legs','abductors','{"glutes","quadriceps"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your hands on your hips.","Step:2 Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.","Step:3 Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Step:4 Repeat on the other side.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/7WaDzyL.gif','https://static.exercisedb.dev/media/7WaDzyL.gif',NULL),
('7WcQgkm','smith machine incline tricep extension - straight variation',NULL,'arms','triceps','{"shoulders"}','machine',NULL,'{"Step:1 Adjust the seat of the smith machine so that the bar is at shoulder height.","Step:2 Sit on the bench with your back against the pad and your feet flat on the ground.","Step:3 Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Extend your arms fully, lifting the bar off the rack and holding it directly above your chest. Focus on straight movement.","Step:5 Lower the bar slowly towards your forehead, keeping your elbows close to your head.","Step:6 Pause for a moment at the bottom, then push the bar back up to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7WcQgkm.gif','https://static.exercisedb.dev/media/7WcQgkm.gif',NULL),
('7xeukSt','scapula dips',NULL,'back','traps','{"rhomboids","deltoids"}','body weight',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and your arms extended in front of you.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.","Step:4 Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7xeukSt.gif','https://static.exercisedb.dev/media/7xeukSt.gif',NULL),
('7xI5MXA','cable bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','cable',NULL,'{"Step:1 Adjust the cable machine to chest height and attach the handles.","Step:2 Stand facing away from the machine with your feet shoulder-width apart.","Step:3 Grasp the handles with an overhand grip and step forward to create tension in the cables.","Step:4 Position your feet firmly on the ground and engage your core.","Step:5 Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.","Step:6 Push the handles forward, extending your arms fully in front of you.","Step:7 Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7xI5MXA.gif','https://static.exercisedb.dev/media/7xI5MXA.gif',NULL),
('7y9JIMj','lever reverse grip preacher curl with precision',NULL,'arms','biceps','{"forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the leverage machine.","Step:2 Grasp the handles with an underhand grip, palms facing up.","Step:3 Rest your upper arms on the preacher pad, ensuring your elbows are fully extended. Maintain precision form throughout.","Step:4 Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Step:5 Pause for a moment at the top of the movement, squeezing your biceps.","Step:6 Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7y9JIMj.gif','https://static.exercisedb.dev/media/7y9JIMj.gif',NULL),
('7zdxRTl','smith leg press',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the seat and footplate of the smith machine to a comfortable position.","Step:2 Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Step:3 Grasp the handles or sides of the machine for stability.","Step:4 Push the footplate away from you by extending your legs, keeping your back against the backrest.","Step:5 Pause for a moment at the fully extended position.","Step:6 Slowly bend your knees and lower the footplate back towards you, returning to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/7zdxRTl.gif','https://static.exercisedb.dev/media/7zdxRTl.gif',NULL),
('82LxxkW','barbell wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.","Step:2 Allow the barbell to roll down to your fingertips, keeping your wrists straight.","Step:3 Slowly curl the barbell up towards your forearms by flexing your wrists.","Step:4 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/82LxxkW.gif','https://static.exercisedb.dev/media/82LxxkW.gif',NULL),
('83HoW9X','barbell upright row v. 2',NULL,'shoulders','delts','{"traps","biceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:2 Let the barbell hang in front of your thighs, arms fully extended.","Step:3 Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Step:4 Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/83HoW9X.gif','https://static.exercisedb.dev/media/83HoW9X.gif',NULL),
('84RyJf8','dumbbell one arm shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Step:2 Press the dumbbell upward until your arm is fully extended overhead.","Step:3 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:4 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/84RyJf8.gif','https://static.exercisedb.dev/media/84RyJf8.gif',NULL),
('84sESNy','dumbbell seated one arm bicep curl on exercise ball with leg raised',NULL,'arms','biceps','{"forearms","shoulders"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Step:3 Place your other hand on your hip for stability.","Step:4 Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.","Step:5 Pause for a moment at the top of the movement, squeezing your bicep.","Step:6 Slowly lower the dumbbell back to the starting position.","Step:7 Repeat for the desired number of repetitions.","Step:8 Switch arms and repeat the exercise."}','https://static.exercisedb.dev/media/84sESNy.gif','https://static.exercisedb.dev/media/84sESNy.gif',NULL),
('89HVjEp','kettlebell seated press with high',NULL,'shoulders','delts','{"triceps","core"}','kettlebell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a kettlebell in each hand at shoulder height, palms facing forward.","Step:3 Press the kettlebells overhead, fully extending your arms. Focus on high movement.","Step:4 Lower the kettlebells back to shoulder height.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/89HVjEp.gif','https://static.exercisedb.dev/media/89HVjEp.gif',NULL),
('8ARQ9Hw','kettlebell sumo high pull',NULL,'back','traps','{"shoulders","glutes","hamstrings"}','kettlebell',NULL,'{"Step:1 Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Step:2 Hold a kettlebell with both hands in front of your body, arms extended downwards.","Step:3 Bend your knees and lower your hips into a squat position, keeping your back straight.","Step:4 Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.","Step:5 As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.","Step:6 Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8ARQ9Hw.gif','https://static.exercisedb.dev/media/8ARQ9Hw.gif',NULL),
('8coXSYU','roller seated shoulder flexor depresor retractor',NULL,'chest','pectorals','{"deltoids","triceps"}','other',NULL,'{"Step:1 Sit on a flat surface with your legs extended in front of you.","Step:2 Hold the roller with both hands, palms facing down, and place it on your thighs.","Step:3 Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.","Step:4 Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8coXSYU.gif','https://static.exercisedb.dev/media/8coXSYU.gif',NULL),
('8d8qJQI','barbell reverse grip incline bench row',NULL,'back','upper back','{"biceps","forearms"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Sit on the bench facing the backrest with your chest against it.","Step:3 Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.","Step:4 Keep your back straight and core engaged.","Step:5 Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top of the movement.","Step:7 Slowly lower the barbell back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8d8qJQI.gif','https://static.exercisedb.dev/media/8d8qJQI.gif',NULL),
('8DiFDVA','dumbbell rear fly',NULL,'shoulders','delts','{"trapezius","rhomboids"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Extend your arms straight down towards the ground, palms facing each other.","Step:4 Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8DiFDVA.gif','https://static.exercisedb.dev/media/8DiFDVA.gif',NULL),
('8eqjhOl','dumbbell palms in incline bench press',NULL,'arms','triceps','{"chest","shoulders"}','dumbbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Sit on the bench with your back against the backrest and feet flat on the ground.","Step:3 Hold a dumbbell in each hand with an overhand grip, palms facing inwards.","Step:4 Extend your arms straight up above your chest, keeping a slight bend in your elbows.","Step:5 Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.","Step:6 Pause for a moment at the bottom, then press the dumbbells back up to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8eqjhOl.gif','https://static.exercisedb.dev/media/8eqjhOl.gif',NULL),
('8fgqP5a','dumbbell standing one arm concentration curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.","Step:2 Place your free hand on your thigh for support.","Step:3 Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Step:4 Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly lower the dumbbell back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/8fgqP5a.gif','https://static.exercisedb.dev/media/8fgqP5a.gif',NULL),
('8gQo5Ss','single style cable standing crunch (with rope attachment)',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Attach a rope to a cable machine at chest height.","Step:2 Stand facing away from the machine with your feet shoulder-width apart. Focus on single movement.","Step:3 Hold the rope with both hands and bring it behind your head, keeping your elbows bent.","Step:4 Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.","Step:5 Pause for a moment at the top of the crunch, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8gQo5Ss.gif','https://static.exercisedb.dev/media/8gQo5Ss.gif',NULL),
('8IbNZwc','rough band hip lift',NULL,'legs','glutes','{"hamstrings","quadriceps"}','resistance band',NULL,'{"Step:1 Lie on your back with your knees bent and feet flat on the ground.","Step:2 Place a resistance band just above your knees.","Step:3 Engage your glutes and core muscles.","Step:4 Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.","Step:5 Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Step:6 Repeat for the desired number of repetitions. Focus on rough movement."}','https://static.exercisedb.dev/media/8IbNZwc.gif','https://static.exercisedb.dev/media/8IbNZwc.gif',NULL),
('8K0w2yA','assisted hanging knee raise with throw down',NULL,'core','abs','{"hip flexors","lower back"}','other',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your knees towards your chest, keeping your legs together.","Step:3 Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.","Step:4 Allow your legs to swing back up and repeat the movement for the desired number of repetitions."}','https://static.exercisedb.dev/media/8K0w2yA.gif','https://static.exercisedb.dev/media/8K0w2yA.gif',NULL),
('8K7m2SS','medicine ball close grip push up',NULL,'arms','triceps','{"chest","shoulders"}','medicine ball',NULL,'{"Step:1 Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Step:2 Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Step:3 Push back up to the starting position, fully extending your arms.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8K7m2SS.gif','https://static.exercisedb.dev/media/8K7m2SS.gif',NULL),
('8oYqOt9','cable seated curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Sit on a cable machine with your feet flat on the ground and your back straight.","Step:2 Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Step:4 Pause for a moment at the top of the movement, squeezing your biceps.","Step:5 Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8oYqOt9.gif','https://static.exercisedb.dev/media/8oYqOt9.gif',NULL),
('8ozhUIZ','barbell standing calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place a barbell across your upper back.","Step:2 Raise your heels off the ground as high as possible, using only your toes.","Step:3 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8ozhUIZ.gif','https://static.exercisedb.dev/media/8ozhUIZ.gif',NULL),
('8urJS9b','weighted hyperextension (on stability ball)',NULL,'back','spine','{"glutes","hamstrings"}','other',NULL,'{"Step:1 Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.","Step:2 Place your hands behind your head or cross them over your chest.","Step:3 Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8urJS9b.gif','https://static.exercisedb.dev/media/8urJS9b.gif',NULL),
('8xUv4J7','cable seated crunch',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Sit on a cable machine with your feet flat on the ground and your knees bent.","Step:2 Hold the cable handle with both hands and position it behind your head.","Step:3 Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.","Step:4 Pause for a moment at the top, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/8xUv4J7.gif','https://static.exercisedb.dev/media/8xUv4J7.gif',NULL),
('8yBgwBS','cable concentration curl tempo',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.","Step:2 Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh. Focus on tempo movement.","Step:3 Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.","Step:4 Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/8yBgwBS.gif','https://static.exercisedb.dev/media/8yBgwBS.gif',NULL),
('903mzG8','smith shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.","Step:2 Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.","Step:4 Press the bar upward until your arms are fully extended overhead.","Step:5 Pause for a moment at the top, then slowly lower the bar back down to shoulder level.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/903mzG8.gif','https://static.exercisedb.dev/media/903mzG8.gif',NULL),
('945zpRg','barbell wide reverse grip bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.","Step:3 Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Step:4 Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.","Step:5 Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/945zpRg.gif','https://static.exercisedb.dev/media/945zpRg.gif',NULL),
('99rWm7w','hamstring stretch',NULL,'legs','hamstrings','{"glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Step forward with your right foot and shift your weight onto your right leg.","Step:3 Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.","Step:4 Hold the stretch for 20-30 seconds, then return to the starting position.","Step:5 Repeat on the other side."}','https://static.exercisedb.dev/media/99rWm7w.gif','https://static.exercisedb.dev/media/99rWm7w.gif',NULL),
('9Ap7miY','decline crunch',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.","Step:2 Place your hands behind your head or across your chest.","Step:3 Engage your abs and lift your upper body towards your knees, curling your torso.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9Ap7miY.gif','https://static.exercisedb.dev/media/9Ap7miY.gif',NULL),
('9c6T1YX','bridge - mountain climber (cross body)',NULL,'core','abs','{"glutes","quadriceps","hamstrings","shoulders","triceps"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.","Step:3 Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.","Step:4 Continue alternating sides, moving at a controlled pace.","Step:5 Keep your hips level and avoid lifting your hips too high or sagging them too low.","Step:6 Maintain a steady breathing pattern throughout the exercise.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9c6T1YX.gif','https://static.exercisedb.dev/media/9c6T1YX.gif',NULL),
('9E25EOx','split squats',NULL,'legs','quads','{"glutes","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Take a step forward with one foot and place it about two feet in front of the other foot.","Step:3 Lower your body by bending your knees and hips, keeping your back straight.","Step:4 Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.","Step:5 Pause for a moment, then push through your front heel to return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs and repeat."}','https://static.exercisedb.dev/media/9E25EOx.gif','https://static.exercisedb.dev/media/9E25EOx.gif',NULL),
('9fCHfSc','pointed cable palm rotational row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Attach a handle to a cable machine at waist height.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the handle with an overhand grip, palms facing down.","Step:4 Step back to create tension on the cable, keeping your back straight and knees slightly bent. Emphasize pointed control.","Step:5 Pull the handle towards your body, rotating your palms to face upwards as you do so.","Step:6 Squeeze your shoulder blades together at the end of the movement.","Step:7 Slowly release the handle back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9fCHfSc.gif','https://static.exercisedb.dev/media/9fCHfSc.gif',NULL),
('9gbyYKk','band seated hip internal rotation',NULL,'legs','glutes','{"hamstrings","quadriceps"}','resistance band',NULL,'{"Step:1 Sit on a chair or bench with your back straight and feet flat on the ground.","Step:2 Place a resistance band around your thighs, just above your knees.","Step:3 Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.","Step:4 Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.","Step:5 Pause for a moment at the end of the movement, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9gbyYKk.gif','https://static.exercisedb.dev/media/9gbyYKk.gif',NULL),
('9GXrTE6','smith one leg floor calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Position yourself on the floor under the smith machine bar, facing away from the machine.","Step:2 Place the balls of your feet on a raised surface, such as a weight plate or block.","Step:3 Position the smith machine bar across your lower legs, just above your ankles.","Step:4 Hold onto the bar with your hands for stability.","Step:5 Raise your heels off the ground by extending your ankles, lifting your body up.","Step:6 Pause at the top of the movement, then slowly lower your heels back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9GXrTE6.gif','https://static.exercisedb.dev/media/9GXrTE6.gif',NULL),
('9IxJdtC','lying leg-hip raise',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended and your arms by your sides.","Step:2 Place your hands under your glutes for support.","Step:3 Engage your core and lift your legs off the ground, raising them towards the ceiling.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9IxJdtC.gif','https://static.exercisedb.dev/media/9IxJdtC.gif',NULL),
('9JprnPh','band single leg calf raise',NULL,'legs','calves','{"ankles","feet"}','resistance band',NULL,'{"Step:1 Stand with your feet hip-width apart and place the band around the ball of your left foot.","Step:2 Hold onto a stable object for balance if needed.","Step:3 Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.","Step:4 Pause for a moment at the top, then slowly lower your left heel back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the right leg."}','https://static.exercisedb.dev/media/9JprnPh.gif','https://static.exercisedb.dev/media/9JprnPh.gif',NULL),
('9KU9TYF','lever horizontal one leg press',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Step:2 Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Step:3 Place your hands on the handles or sides of the machine for stability.","Step:4 Push the footplate away from your body by extending your leg, keeping your back against the backrest.","Step:5 Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/9KU9TYF.gif','https://static.exercisedb.dev/media/9KU9TYF.gif',NULL),
('9n2149Z','sled lying squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the sled machine to a comfortable weight.","Step:2 Lie on your back on the sled machine with your feet on the footplate.","Step:3 Position your feet shoulder-width apart and slightly angled outwards.","Step:4 Grip the handles of the sled machine for stability.","Step:5 Engage your glutes and core muscles.","Step:6 Push through your heels and extend your legs to lift the sled.","Step:7 Lower the sled back down by bending your knees and hips.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9n2149Z.gif','https://static.exercisedb.dev/media/9n2149Z.gif',NULL),
('9pa4H5m','band horizontal pallof press',NULL,'core','abs','{"obliques","glutes"}','resistance band',NULL,'{"Step:1 Attach the band to a sturdy anchor point at waist height.","Step:2 Stand perpendicular to the anchor point with your feet shoulder-width apart.","Step:3 Grasp the band handle with both hands and step away from the anchor point to create tension in the band.","Step:4 Bring your hands to your chest, keeping your elbows bent and close to your body.","Step:5 Engage your core and maintain a stable stance.","Step:6 Extend your arms straight out in front of you, pushing the band away from your body.","Step:7 Hold the extended position for a few seconds, focusing on maintaining tension in your core.","Step:8 Slowly bring your hands back to your chest, resisting the pull of the band.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9pa4H5m.gif','https://static.exercisedb.dev/media/9pa4H5m.gif',NULL),
('9pQSkH8','dumbbell reverse grip incline bench two arm row',NULL,'back','upper back','{"biceps","forearms"}','dumbbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Sit on the bench with your chest against the backrest and your feet flat on the ground.","Step:3 Hold a dumbbell in each hand with an underhand grip.","Step:4 Lean forward and let your arms hang straight down, fully extended.","Step:5 Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9pQSkH8.gif','https://static.exercisedb.dev/media/9pQSkH8.gif',NULL),
('9RT8oQW','bench dip on floor',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Step:2 Slide your butt off the bench, supporting your weight with your hands.","Step:3 Lower your body by bending your elbows until your upper arms are parallel to the floor.","Step:4 Push yourself back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9RT8oQW.gif','https://static.exercisedb.dev/media/9RT8oQW.gif',NULL),
('9sgNE2O','barbell decline pullover',NULL,'chest','pectorals','{"triceps","shoulders"}','barbell',NULL,'{"Step:1 Lie down on a decline bench with your head lower than your hips and your feet secured.","Step:2 Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.","Step:3 Extend your arms above your chest, keeping a slight bend in your elbows.","Step:4 Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.","Step:5 Pause for a moment, then return the barbell to the starting position by reversing the motion.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9sgNE2O.gif','https://static.exercisedb.dev/media/9sgNE2O.gif',NULL),
('9Tkqa9O','kettlebell windmill',NULL,'core','abs','{"obliques","shoulders"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.","Step:2 Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.","Step:3 Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.","Step:4 Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.","Step:5 Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/9Tkqa9O.gif','https://static.exercisedb.dev/media/9Tkqa9O.gif',NULL),
('9tvVVM9','flexible cable triceps pushdown (v-bar)',NULL,'arms','triceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a v-bar attachment to the cable machine at the highest setting.","Step:2 Stand facing the cable machine with your feet shoulder-width apart.","Step:3 Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Step:5 Engage your triceps and exhale as you push the v-bar down until your arms are fully extended. Perform with flexible intensity.","Step:6 Pause for a moment at the bottom of the movement, squeezing your triceps.","Step:7 Inhale as you slowly return the v-bar to the starting position, maintaining control.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9tvVVM9.gif','https://static.exercisedb.dev/media/9tvVVM9.gif',NULL),
('9vz4JlC','weighted lunge with swing twisted',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a weight in each hand.","Step:2 Take a step forward with your right foot, lowering your body into a lunge position.","Step:3 As you lunge forward, swing the weights forward and upward, keeping your arms straight.","Step:4 Push off with your right foot and return to the starting position, swinging the weights back down.","Step:5 (twisted variation) Repeat with your left foot and continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/9vz4JlC.gif','https://static.exercisedb.dev/media/9vz4JlC.gif',NULL),
('9WTm7dq','chest dip',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Position yourself on parallel bars with your arms fully extended and your body straight.","Step:2 Lower your body by bending your elbows until your shoulders are below your elbows.","Step:3 Push yourself back up to the starting position by straightening your arms.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9WTm7dq.gif','https://static.exercisedb.dev/media/9WTm7dq.gif',NULL),
('9XjtHvS','dumbbell pullover',NULL,'chest','pectorals','{"latissimus dorsi","triceps"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your head at one end and your feet on the floor.","Step:2 Hold a dumbbell with both hands and extend your arms straight above your chest.","Step:3 Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.","Step:4 Pause for a moment, then raise the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9XjtHvS.gif','https://static.exercisedb.dev/media/9XjtHvS.gif',NULL),
('9Z23cLE','barbell incline bench press seated',NULL,'chest','pectorals','{"shoulders","triceps"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 (seated variation) Lie down on the bench with your feet flat on the ground.","Step:3 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.","Step:5 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9Z23cLE.gif','https://static.exercisedb.dev/media/9Z23cLE.gif',NULL),
('9ZGnq1w','triceps dip (between benches) - extreme variation',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Step:2 (extreme variation) Slide your butt off the bench, supporting your weight with your hands.","Step:3 Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/9ZGnq1w.gif','https://static.exercisedb.dev/media/9ZGnq1w.gif',NULL),
('9ZGZuOD','incline twisting sit-up',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Lie down on the bench with your feet secured under the foot pads.","Step:3 Place your hands behind your head or across your chest.","Step:4 Engage your abs and lift your upper body off the bench, curling forward.","Step:5 As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.","Step:6 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:7 Repeat the movement, this time twisting your torso to the other side.","Step:8 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/9ZGZuOD.gif','https://static.exercisedb.dev/media/9ZGZuOD.gif',NULL),
('A2upspL','one leg donkey calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes pointing forward.","Step:2 Place your hands on a stable surface for support, such as a wall or a bar.","Step:3 Lift one leg off the ground, keeping your knee slightly bent.","Step:4 Raise your heel as high as possible, using your calf muscles.","Step:5 Pause for a moment at the top, then slowly lower your heel back down.","Step:6 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/A2upspL.gif','https://static.exercisedb.dev/media/A2upspL.gif',NULL),
('A3P4O0R','cable seated row with reverse',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Step:2 Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.","Step:3 Pull the handles towards your body, squeezing your shoulder blades together. Focus on reverse movement.","Step:4 Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/A3P4O0R.gif','https://static.exercisedb.dev/media/A3P4O0R.gif',NULL),
('a4F9Oyc','kettlebell double alternating hang clean',NULL,'arms','biceps','{"forearms","shoulders"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Step:3 Allow the kettlebells to hang straight down in front of your body.","Step:4 In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.","Step:5 As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.","Step:6 Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.","Step:7 Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/a4F9Oyc.gif','https://static.exercisedb.dev/media/a4F9Oyc.gif',NULL),
('A6wtbuL','dumbbell standing overhead press',NULL,'shoulders','delts','{"triceps","upper back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Step:2 Press the dumbbells upward until your arms are fully extended overhead.","Step:3 Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/A6wtbuL.gif','https://static.exercisedb.dev/media/A6wtbuL.gif',NULL),
('a8VDgLw','stationary bike walk',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the seat height and position on the stationary bike to ensure proper alignment.","Step:2 Place your feet on the pedals and secure them with the straps if available.","Step:3 Start pedaling at a comfortable pace, keeping your back straight and core engaged.","Step:4 Maintain a steady rhythm and increase the resistance level if desired.","Step:5 Continue pedaling for the desired duration of your cardio workout.","Step:6 Cool down by gradually reducing your pace and resistance level.","Step:7 Stretch your leg muscles after the workout to prevent tightness and promote recovery."}','https://static.exercisedb.dev/media/a8VDgLw.gif','https://static.exercisedb.dev/media/a8VDgLw.gif',NULL),
('A9qxk2F','archer push up',NULL,'chest','pectorals','{"triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands slightly wider than shoulder-width apart.","Step:2 Extend one arm straight out to the side, parallel to the ground.","Step:3 Lower your body by bending your elbows, keeping your back straight and core engaged.","Step:4 Push back up to the starting position.","Step:5 Repeat on the other side, extending the opposite arm out to the side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/A9qxk2F.gif','https://static.exercisedb.dev/media/A9qxk2F.gif',NULL),
('aaxA3cm','smith reverse grip bent over row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Set up the smith machine with the bar at hip height.","Step:2 Stand facing the bar with your feet shoulder-width apart.","Step:3 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:4 Grasp the bar with an underhand grip, hands shoulder-width apart.","Step:5 Pull the bar towards your lower chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/aaxA3cm.gif','https://static.exercisedb.dev/media/aaxA3cm.gif',NULL),
('aaXr7ld','lever t bar row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and footplate position to ensure proper alignment.","Step:2 Sit on the machine with your chest against the pad and your feet flat on the footplate.","Step:3 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Keep your back straight and engage your core.","Step:5 Pull the handles towards your torso, squeezing your shoulder blades together.","Step:6 Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/aaXr7ld.gif','https://static.exercisedb.dev/media/aaXr7ld.gif',NULL),
('aDoFKrE','medicine ball chest pass',NULL,'chest','pectorals','{"shoulders","triceps"}','medicine ball',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Step:2 Extend your arms forward, pushing the medicine ball away from your chest with force.","Step:3 As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.","Step:4 Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.","Step:5 Continue for the desired number of repetitions."}','https://static.exercisedb.dev/media/aDoFKrE.gif','https://static.exercisedb.dev/media/aDoFKrE.gif',NULL),
('AdxxqfF','barbell standing reverse grip curl resistance',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Step:2 Keep your elbows close to your torso and your upper arms stationary.","Step:3 Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions. Focus on resistance movement."}','https://static.exercisedb.dev/media/AdxxqfF.gif','https://static.exercisedb.dev/media/AdxxqfF.gif',NULL),
('ae9UoXQ','dumbbell incline curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.","Step:2 Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.","Step:3 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ae9UoXQ.gif','https://static.exercisedb.dev/media/ae9UoXQ.gif',NULL),
('aee2Fcj','barbell biceps curl (with arm blaster)',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Step:2 Place your upper arms against the arm blaster, keeping your elbows close to your torso.","Step:3 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the barbell back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/aee2Fcj.gif','https://static.exercisedb.dev/media/aee2Fcj.gif',NULL),
('Af0EW2I','muscle-up (on vertical bar)',NULL,'back','lats','{"biceps","triceps","forearms"}','body weight',NULL,'{"Step:1 Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.","Step:2 Engage your core and pull your body up towards the bar, leading with your chest.","Step:3 As you pull yourself up, lean back slightly and bring your elbows towards your sides.","Step:4 Continue pulling until your chest reaches the bar and your elbows are fully bent.","Step:5 Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Af0EW2I.gif','https://static.exercisedb.dev/media/Af0EW2I.gif',NULL),
('afv0ZAS','upright smith incline bench press',NULL,'chest','pectorals','{"shoulders","triceps"}','machine',NULL,'{"Step:1 Adjust the bench to a 30-45 degree incline.","Step:2 Sit on the bench with your back flat against the pad and feet firmly on the ground.","Step:3 Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Perform with upright intensity.","Step:4 Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.","Step:5 Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/afv0ZAS.gif','https://static.exercisedb.dev/media/afv0ZAS.gif',NULL),
('aHDy5O5','band y-raise',NULL,'shoulders','delts','{"traps","rhomboids"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.","Step:2 Keep your arms straight and lift them up and out to the sides, forming a 'Y' shape with your body.","Step:3 Squeeze your shoulder blades together at the top of the movement.","Step:4 Slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/aHDy5O5.gif','https://static.exercisedb.dev/media/aHDy5O5.gif',NULL),
('ainizkb','dumbbell upright row',NULL,'shoulders','delts','{"traps","biceps"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Step:2 Let the dumbbells hang in front of your thighs, with your arms fully extended.","Step:3 Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Step:4 Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ainizkb.gif','https://static.exercisedb.dev/media/ainizkb.gif',NULL),
('Aj9vWh7','isolation assisted seated pectoralis major stretch with stability ball',NULL,'chest','pectorals','{"shoulders","triceps"}','other',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your back straight.","Step:2 Hold a stability ball with both hands and extend your arms straight out in front of you.","Step:3 Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.","Step:4 Hold the stretch for a few seconds, then slowly return to the starting position. Emphasize isolation control.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Aj9vWh7.gif','https://static.exercisedb.dev/media/Aj9vWh7.gif',NULL),
('Al3tP0D','medicine ball supine chest throw',NULL,'arms','triceps','{"chest","shoulders"}','medicine ball',NULL,'{"Step:1 Lie flat on your back on a bench with your knees bent and feet flat on the ground.","Step:2 Hold the medicine ball with both hands, extending your arms straight up above your chest.","Step:3 Lower the medicine ball towards your chest, keeping your elbows close to your body.","Step:4 Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.","Step:5 Catch the medicine ball and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Al3tP0D.gif','https://static.exercisedb.dev/media/Al3tP0D.gif',NULL),
('Am02iPd','dumbbell one arm fly on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Step:2 Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.","Step:3 Extend your arm with the dumbbell straight up above your chest, palm facing inwards.","Step:4 Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Step:5 Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/Am02iPd.gif','https://static.exercisedb.dev/media/Am02iPd.gif',NULL),
('ANbbry2','lower back curl',NULL,'back','spine','{"glutes","hamstrings"}','body weight',NULL,'{"Step:1 Lie flat on your stomach with your legs extended and your arms by your sides.","Step:2 Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.","Step:3 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ANbbry2.gif','https://static.exercisedb.dev/media/ANbbry2.gif',NULL),
('AQ0mC4Y','dumbbell full can lateral raise',NULL,'shoulders','delts','{"traps","rotator cuff"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Step:2 Keep your back straight and engage your core.","Step:3 Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/AQ0mC4Y.gif','https://static.exercisedb.dev/media/AQ0mC4Y.gif',NULL),
('AQIhRjM','lying elbow to knee',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","Step:4 At the same time, extend your right leg straight out and lift it off the ground.","Step:5 Pause for a moment, then return to the starting position.","Step:6 Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/AQIhRjM.gif','https://static.exercisedb.dev/media/AQIhRjM.gif',NULL),
('aqvSOQE','cable cross-over revers fly',NULL,'shoulders','delts','{"rhomboids","trapezius"}','cable',NULL,'{"Step:1 Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.","Step:2 Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.","Step:3 Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.","Step:4 With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.","Step:5 Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/aqvSOQE.gif','https://static.exercisedb.dev/media/aqvSOQE.gif',NULL),
('AR0ig3o','flexion leg sit up (bent knee)',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.","Step:5 Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/AR0ig3o.gif','https://static.exercisedb.dev/media/AR0ig3o.gif',NULL),
('arsYEd3','band one arm single leg split squat',NULL,'legs','quads','{"glutes","hamstrings"}','resistance band',NULL,'{"Step:1 Stand with your feet hip-width apart and place a resistance band around your ankles.","Step:2 Extend one leg forward and rest the top of your foot on a bench or step behind you.","Step:3 Hold onto a support with one hand for balance.","Step:4 Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.","Step:5 Push through your heel to return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/arsYEd3.gif','https://static.exercisedb.dev/media/arsYEd3.gif',NULL),
('arvaszz','modified push up to lower arms',NULL,'arms','forearms','{"triceps","chest","shoulders"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands directly under your shoulders and your body in a straight line.","Step:2 Lower your body down towards the ground by bending your elbows, keeping them close to your sides.","Step:3 Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.","Step:4 Pause for a moment, then push through your palms to lift your forearms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/arvaszz.gif','https://static.exercisedb.dev/media/arvaszz.gif',NULL),
('aTNKZiC','dumbbell incline one arm lateral raise',NULL,'shoulders','delts','{"trapezius","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.","Step:2 Lean forward and position your upper arm against the inside of your thigh.","Step:3 Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.","Step:4 Continue lifting until your arm is parallel to the floor.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/aTNKZiC.gif','https://static.exercisedb.dev/media/aTNKZiC.gif',NULL),
('aumB2IV','assisted sit-up',NULL,'core','abs','{"hip flexors"}','other',NULL,'{"Step:1 Sit on the edge of a bench or have someone hold your feet down.","Step:2 Lie flat on your back with your knees bent and feet flat on the ground.","Step:3 Place your hands behind your head with your elbows pointing outwards.","Step:4 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:5 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/aumB2IV.gif','https://static.exercisedb.dev/media/aumB2IV.gif',NULL),
('aVs3BR3','cable twist',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart, facing the cable machine.","Step:2 Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Step:3 Engage your core and twist your torso to the right, pulling the cable across your body.","Step:4 Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.","Step:5 Slowly return to the starting position, resisting the cable's pull.","Step:6 Repeat the movement to the left side.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/aVs3BR3.gif','https://static.exercisedb.dev/media/aVs3BR3.gif',NULL),
('AwAIlSo','squared reverse grip machine lat pulldown',NULL,'back','lats','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Step:2 Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Step:3 Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Step:4 Pull the handles down towards your chest, squeezing your shoulder blades together. Maintain squared form throughout.","Step:5 Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/AwAIlSo.gif','https://static.exercisedb.dev/media/AwAIlSo.gif',NULL),
('aWedzZX','glute bridge two legs on bench (male)',NULL,'legs','glutes','{"hamstrings","core"}','body weight',NULL,'{"Step:1 Sit on the edge of a bench with your back against it and your feet flat on the ground.","Step:2 Place your hands on the bench beside your hips for support.","Step:3 Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Step:4 Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/aWedzZX.gif','https://static.exercisedb.dev/media/aWedzZX.gif',NULL),
('awG04cF','finger curls',NULL,'arms','forearms','{"wrist flexors","grip muscles"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Step:2 Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Step:3 Slowly curl your fingers towards your palms, squeezing the barbell tightly.","Step:4 Hold the contraction for a moment, then slowly release your fingers back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/awG04cF.gif','https://static.exercisedb.dev/media/awG04cF.gif',NULL),
('AX1kB0o','twist hip lift',NULL,'legs','glutes','{"obliques","hamstrings"}','body weight',NULL,'{"Step:1 Lie on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands by your sides for support.","Step:3 Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Step:4 While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.","Step:5 Return to the starting position and repeat the twist to the left side.","Step:6 Continue alternating twists for the desired number of repetitions."}','https://static.exercisedb.dev/media/AX1kB0o.gif','https://static.exercisedb.dev/media/AX1kB0o.gif',NULL),
('aXcUyKb','kettlebell one arm snatch',NULL,'shoulders','delts','{"trapezius","forearms","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.","Step:2 Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Step:3 Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.","Step:4 As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.","Step:5 Lower the kettlebell back down between your legs and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/aXcUyKb.gif','https://static.exercisedb.dev/media/aXcUyKb.gif',NULL),
('AxFoqAD','hack one leg calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the sled machine to an appropriate weight.","Step:2 Stand on the sled machine with one foot, keeping the other foot off the ground.","Step:3 Hold onto the handles for stability.","Step:4 Raise your heel as high as possible, lifting your body up on the ball of your foot.","Step:5 Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Step:6 Repeat for the desired number of repetitions.","Step:7 Switch legs and repeat the exercise."}','https://static.exercisedb.dev/media/AxFoqAD.gif','https://static.exercisedb.dev/media/AxFoqAD.gif',NULL),
('aXtJhlg','dumbbell step-up',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Step:2 Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step:3 Push through your right heel and lift your body up onto the bench or step, straightening your right leg.","Step:4 Bring your left foot up onto the bench or step, standing fully upright.","Step:5 Step back down with your left foot, followed by your right foot, returning to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/aXtJhlg.gif','https://static.exercisedb.dev/media/aXtJhlg.gif',NULL),
('ayAHcEm','smith incline shoulder raises',NULL,'chest','serratus anterior','{"deltoids","trapezius"}','machine',NULL,'{"Step:1 Adjust the smith machine to an incline position.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Keep your back straight and core engaged.","Step:5 Raise the barbell up towards the ceiling, leading with your elbows.","Step:6 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ayAHcEm.gif','https://static.exercisedb.dev/media/ayAHcEm.gif',NULL),
('B1EVP9F','incline push-up',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Step:2 Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Step:3 Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/B1EVP9F.gif','https://static.exercisedb.dev/media/B1EVP9F.gif',NULL),
('b2Uoz54','barbell front raise',NULL,'shoulders','delts','{"biceps","triceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Step:2 Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.","Step:3 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/b2Uoz54.gif','https://static.exercisedb.dev/media/b2Uoz54.gif',NULL),
('B3Rxp6L','dumbbell incline breeding',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Sit on the bench with your back against the pad and feet flat on the ground.","Step:3 Hold a dumbbell in each hand with an overhand grip, palms facing forward.","Step:4 Start with your arms fully extended, perpendicular to the ground.","Step:5 Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Step:6 Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/B3Rxp6L.gif','https://static.exercisedb.dev/media/B3Rxp6L.gif',NULL),
('b4b6afT','weighted seated bicep curl (on stability ball)',NULL,'arms','biceps','{"forearms"}','medicine ball',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your back straight.","Step:2 Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.","Step:3 Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Inhale and slowly lower the medicine ball back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/b4b6afT.gif','https://static.exercisedb.dev/media/b4b6afT.gif',NULL),
('b5uBMv2','exercise ball alternating arm ups with fast',NULL,'back','lats','{"shoulders","core"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.","Step:3 Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent. Perform with fast intensity.","Step:4 Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Step:5 Repeat the movement with the other arm.","Step:6 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/b5uBMv2.gif','https://static.exercisedb.dev/media/b5uBMv2.gif',NULL),
('B5xca8s','hands clasped circular toe touch (male)',NULL,'legs','glutes','{"hamstrings","quadriceps","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.","Step:4 Pause for a moment at the bottom, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/B5xca8s.gif','https://static.exercisedb.dev/media/B5xca8s.gif',NULL),
('b63ZzGe','potty squat with support',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes pointing slightly outward.","Step:2 Hold onto a stable support, such as a chair or wall, for balance.","Step:3 Lower your body down into a squat position by bending your knees and pushing your hips back.","Step:4 Keep your chest up and your back straight throughout the movement.","Step:5 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/b63ZzGe.gif','https://static.exercisedb.dev/media/b63ZzGe.gif',NULL),
('B6dAO1t','smith seated wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','machine',NULL,'{"Step:1 Sit on a bench in front of a Smith machine with your feet flat on the ground.","Step:2 Grasp the barbell with an underhand grip, hands shoulder-width apart.","Step:3 Rest your forearms on your thighs, allowing your wrists to hang off.","Step:4 Slowly curl your wrists upward, bringing the barbell towards your forearms.","Step:5 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/B6dAO1t.gif','https://static.exercisedb.dev/media/B6dAO1t.gif',NULL),
('b6hQYMb','lever preacher curl',NULL,'arms','biceps','{"forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the leverage machine.","Step:2 Place your upper arms on the pad and grip the handles with an underhand grip.","Step:3 Keep your back straight and your elbows positioned on the pad.","Step:4 Exhale and curl your forearms towards your upper arms, contracting your biceps.","Step:5 Pause for a moment at the top of the movement, squeezing your biceps.","Step:6 Inhale and slowly lower the handles back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/b6hQYMb.gif','https://static.exercisedb.dev/media/b6hQYMb.gif',NULL),
('b9kqlBy','kettlebell alternating renegade row',NULL,'back','upper back','{"core","shoulders"}','kettlebell',NULL,'{"Step:1 Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.","Step:2 Engage your core and keep your body in a straight line from head to heels.","Step:3 Pull one kettlebell up towards your chest, keeping your elbow close to your body.","Step:4 Lower the kettlebell back down to the starting position and repeat with the other arm.","Step:5 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/b9kqlBy.gif','https://static.exercisedb.dev/media/b9kqlBy.gif',NULL),
('BaE7O6U','hanging oblique knee raise',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.","Step:3 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:4 Repeat on the other side, twisting your torso in the opposite direction.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/BaE7O6U.gif','https://static.exercisedb.dev/media/BaE7O6U.gif',NULL),
('BbfB8Gb','basic toe touch (male)',NULL,'legs','glutes','{"hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your arms by your sides.","Step:2 Bend forward at the waist, keeping your back straight and your knees slightly bent.","Step:3 Reach down towards your toes with your hands, keeping your legs as straight as possible.","Step:4 Pause for a moment at the bottom, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BbfB8Gb.gif','https://static.exercisedb.dev/media/BbfB8Gb.gif',NULL),
('bBi35y3','dumbbell standing alternate overhead press',NULL,'shoulders','delts','{"triceps","core"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Step:2 Press one dumbbell overhead, fully extending your arm.","Step:3 Lower the dumbbell back to shoulder level.","Step:4 Repeat with the other arm.","Step:5 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/bBi35y3.gif','https://static.exercisedb.dev/media/bBi35y3.gif',NULL),
('bbLR7fB','band lying straight leg raise',NULL,'core','abs','{"hip flexors"}','resistance band',NULL,'{"Step:1 Lie flat on your back with your legs straight and your feet together.","Step:2 Place the band around the arches of your feet and hold the ends of the band with your hands.","Step:3 Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bbLR7fB.gif','https://static.exercisedb.dev/media/bbLR7fB.gif',NULL),
('BCGQ6J5','cable close grip curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a straight bar to a low pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Step:3 Grasp the bar with an underhand grip, hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Step:5 Exhale and curl the bar up towards your shoulders, contracting your biceps.","Step:6 Pause for a moment at the top of the movement, squeezing your biceps.","Step:7 Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BCGQ6J5.gif','https://static.exercisedb.dev/media/BCGQ6J5.gif',NULL),
('BCs0G2F','barbell sitted alternate leg raise (female)',NULL,'core','abs','{"hip flexors","quadriceps"}','barbell',NULL,'{"Step:1 Sit on a bench with your back straight and hold a barbell across your thighs.","Step:2 Place your hands on the sides of the bench for support.","Step:3 Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.","Step:4 Lower the leg back down and repeat with the other leg.","Step:5 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/BCs0G2F.gif','https://static.exercisedb.dev/media/BCs0G2F.gif',NULL),
('BCUR88E','dumbbell standing one arm extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Step:2 Raise the dumbbell overhead, fully extending your arm.","Step:3 Keep your upper arm close to your head and perpendicular to the ground.","Step:4 Slowly lower the dumbbell behind your head, bending your elbow.","Step:5 Pause for a moment, then raise the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BCUR88E.gif','https://static.exercisedb.dev/media/BCUR88E.gif',NULL),
('bd5b860','wrist rollerer',NULL,'arms','forearms','{"biceps","triceps"}','other',NULL,'{"Step:1 Attach a weight to one end of a rope or bar.","Step:2 Hold the other end of the rope or bar with both hands, palms facing down.","Step:3 Stand with your feet shoulder-width apart and your arms fully extended in front of you.","Step:4 Slowly roll the weight up towards your hands by flexing your wrists.","Step:5 Pause for a moment at the top, then slowly lower the weight back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bd5b860.gif','https://static.exercisedb.dev/media/bd5b860.gif',NULL),
('bdWcbaU','frankenstein squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.","Step:2 Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.","Step:3 Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:4 Pause for a moment, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bdWcbaU.gif','https://static.exercisedb.dev/media/bdWcbaU.gif',NULL),
('BeReYBf','side-to-side chin with reverse',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Hang from the bar with your arms fully extended and your body relaxed.","Step:4 Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight. Perform with reverse intensity.","Step:5 Once your chin is above the bar, lower yourself back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BeReYBf.gif','https://static.exercisedb.dev/media/BeReYBf.gif',NULL),
('bfiHMpI','dumbbell incline press on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in each hand, palms facing forward.","Step:2 Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.","Step:3 Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Step:4 Press the dumbbells upward, extending your arms fully.","Step:5 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bfiHMpI.gif','https://static.exercisedb.dev/media/bfiHMpI.gif',NULL),
('Bg5JKSH','dumbbell incline one arm press on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.","Step:2 Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.","Step:3 Hold the dumbbell at shoulder height with your palm facing forward.","Step:4 Press the dumbbell upward until your arm is fully extended.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/Bg5JKSH.gif','https://static.exercisedb.dev/media/Bg5JKSH.gif',NULL),
('BgljGjd','lever reverse t-bar row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and footplate position on the leverage machine.","Step:2 Sit on the machine with your chest against the pad and your feet flat on the footplate.","Step:3 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Keep your back straight and engage your core.","Step:5 Pull the handles towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BgljGjd.gif','https://static.exercisedb.dev/media/BgljGjd.gif',NULL),
('BIb1tGo','dumbbell standing one arm curl (over incline bench)',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.","Step:2 Place your other hand on an incline bench for support.","Step:3 Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Step:4 Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/BIb1tGo.gif','https://static.exercisedb.dev/media/BIb1tGo.gif',NULL),
('BJ0Hz5L','dumbbell bent over row',NULL,'back','upper back','{"biceps","forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.","Step:2 Bend forward at the hips, keeping your back straight and your core engaged.","Step:3 Let your arms hang straight down towards the floor, with your elbows slightly bent.","Step:4 Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BJ0Hz5L.gif','https://static.exercisedb.dev/media/BJ0Hz5L.gif',NULL),
('bjqbauy','weighted standing hand squeeze',NULL,'arms','forearms','{"biceps","triceps"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a weight in each hand.","Step:2 Extend your arms straight in front of you, palms facing each other.","Step:3 Squeeze your hands together as hard as you can, engaging your forearms.","Step:4 Hold the squeeze for a few seconds, then release.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bjqbauy.gif','https://static.exercisedb.dev/media/bjqbauy.gif',NULL),
('bJYHBIN','bodyweight standing calf raise',NULL,'legs','calves','{"ankles","feet"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes pointing forward.","Step:2 Place your hands on a wall or stable surface for balance.","Step:3 Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.","Step:4 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bJYHBIN.gif','https://static.exercisedb.dev/media/bJYHBIN.gif',NULL),
('BKa8dmT','dumbbell over bench neutral wrist curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Step:2 Rest your forearms on the bench, allowing your wrists to hang off the edge.","Step:3 Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.","Step:4 Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BKa8dmT.gif','https://static.exercisedb.dev/media/BKa8dmT.gif',NULL),
('bKWbrTA','one arm towel row',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Step:2 Bend forward at the waist, keeping your back straight and your core engaged.","Step:3 Extend your arm fully, allowing the towel to hang in front of you.","Step:4 Pull the towel towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower the towel back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/bKWbrTA.gif','https://static.exercisedb.dev/media/bKWbrTA.gif',NULL),
('BkxB8LW','kettlebell seated press',NULL,'shoulders','delts','{"triceps","core"}','kettlebell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a kettlebell in each hand at shoulder height, palms facing forward.","Step:3 Press the kettlebells overhead, fully extending your arms.","Step:4 Lower the kettlebells back to shoulder height.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BkxB8LW.gif','https://static.exercisedb.dev/media/BkxB8LW.gif',NULL),
('BL3GHeY','straddle planche',NULL,'core','abs','{"shoulders","triceps","chest"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.","Step:2 Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.","Step:3 Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.","Step:4 Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BL3GHeY.gif','https://static.exercisedb.dev/media/BL3GHeY.gif',NULL),
('blBXysN','kettlebell two arm military press',NULL,'shoulders','delts','{"triceps","upper back"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.","Step:2 Engage your core and press the kettlebells overhead, fully extending your arms.","Step:3 Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/blBXysN.gif','https://static.exercisedb.dev/media/blBXysN.gif',NULL),
('BLCvwr2','dumbbell reverse wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground.","Step:2 Hold a dumbbell in each hand with an overhand grip, palms facing down.","Step:3 Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Step:4 Slowly curl your wrists upward, bringing the dumbbells towards your body.","Step:5 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BLCvwr2.gif','https://static.exercisedb.dev/media/BLCvwr2.gif',NULL),
('bLyQokI','london bridge',NULL,'back','upper back','{"shoulders","biceps","forearms"}','other',NULL,'{"Step:1 Attach the rope to a high anchor point.","Step:2 Stand facing away from the anchor point with your feet shoulder-width apart.","Step:3 Grasp the rope with an overhand grip, palms facing down.","Step:4 Lean forward slightly, keeping your back straight and core engaged.","Step:5 Pull the rope towards your body, squeezing your shoulder blades together.","Step:6 Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bLyQokI.gif','https://static.exercisedb.dev/media/bLyQokI.gif',NULL),
('bmBf7LN','dumbbell lying external shoulder rotation',NULL,'shoulders','delts','{"rotator cuff","triceps"}','dumbbell',NULL,'{"Step:1 Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.","Step:2 Hold a dumbbell in your hand with your palm facing down.","Step:3 Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.","Step:4 Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/bmBf7LN.gif','https://static.exercisedb.dev/media/bmBf7LN.gif',NULL),
('BMMolZ3','tuck crunch',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.","Step:4 Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BMMolZ3.gif','https://static.exercisedb.dev/media/BMMolZ3.gif',NULL),
('BmrwWzo','dumbbell sumo pull through',NULL,'legs','glutes','{"hamstrings","quadriceps","core"}','dumbbell',NULL,'{"Step:1 Stand with your feet wider than shoulder-width apart, toes pointed outwards.","Step:2 Hold a dumbbell with both hands in front of your body, arms extended.","Step:3 Bend your knees and lower your hips down into a squat position, keeping your back straight.","Step:4 Lower the dumbbell down between your legs, keeping your arms straight.","Step:5 Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.","Step:6 Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BmrwWzo.gif','https://static.exercisedb.dev/media/BmrwWzo.gif',NULL),
('bmwlYvD','gorilla chin',NULL,'core','abs','{"forearms","biceps"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Hang from the bar with your arms fully extended and your palms facing away from you.","Step:4 Engage your core and pull your body up towards the bar, bringing your chin above the bar.","Step:5 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bmwlYvD.gif','https://static.exercisedb.dev/media/bmwlYvD.gif',NULL),
('Bn6TXyO','sit-up v. 2',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Bn6TXyO.gif','https://static.exercisedb.dev/media/Bn6TXyO.gif',NULL),
('bndCa3Q','barbell pin presses',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Set up a barbell on a power rack at chest height.","Step:2 Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.","Step:3 Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.","Step:5 Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.","Step:6 Pause for a moment when the barbell touches your chest.","Step:7 Push the barbell back up to the starting position, fully extending your arms.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bndCa3Q.gif','https://static.exercisedb.dev/media/bndCa3Q.gif',NULL),
('bOOdeyc','lever seated calf raise',NULL,'legs','calves','{"soleus","ankle stabilizers"}','machine',NULL,'{"Step:1 Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Step:2 Place your toes on the footplate with your heels hanging off the edge.","Step:3 Grasp the handles or the sides of the seat for stability.","Step:4 Push through the balls of your feet to raise your heels as high as possible.","Step:5 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bOOdeyc.gif','https://static.exercisedb.dev/media/bOOdeyc.gif',NULL),
('bpJL2Qs','dumbbell pronate-grip triceps extension',NULL,'arms','triceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.","Step:3 Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.","Step:4 Pause for a moment, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bpJL2Qs.gif','https://static.exercisedb.dev/media/bpJL2Qs.gif',NULL),
('Bpkf41o','dumbbell one arm chest fly on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Step:2 Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.","Step:3 Extend your arm with the dumbbell straight up above your chest, palm facing inward.","Step:4 Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Step:5 Pause for a moment when your arm is parallel to the ground.","Step:6 Engage your chest muscles to bring the dumbbell back up to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/Bpkf41o.gif','https://static.exercisedb.dev/media/Bpkf41o.gif',NULL),
('BqgCRif','dumbbell cuban press v. 2',NULL,'shoulders','delts','{"triceps","upper back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Step:2 Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.","Step:3 Rotate your wrists so that your palms are facing forward.","Step:4 Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BqgCRif.gif','https://static.exercisedb.dev/media/BqgCRif.gif',NULL),
('bQHPBU3','dumbbell one arm pullover on exercise ball',NULL,'chest','pectorals','{"triceps","latissimus dorsi","rhomboids"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Hold a dumbbell with one hand and extend your arm straight up above your chest.","Step:3 Slowly lower the dumbbell behind your head while keeping your arm straight.","Step:4 Pause for a moment, then raise the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/bQHPBU3.gif','https://static.exercisedb.dev/media/bQHPBU3.gif',NULL),
('bQy2Eni','dumbbell one arm kickback',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Step:4 Extend your right arm straight back, squeezing your triceps at the top of the movement.","Step:5 Slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/bQy2Eni.gif','https://static.exercisedb.dev/media/bQy2Eni.gif',NULL),
('BReCuOn','bodyweight squatting row (with towel)',NULL,'back','upper back','{"biceps","shoulders"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.","Step:2 Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.","Step:3 As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.","Step:4 Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BReCuOn.gif','https://static.exercisedb.dev/media/BReCuOn.gif',NULL),
('BRImeP8','lever seated dip',NULL,'arms','triceps','{"chest","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.","Step:2 Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.","Step:3 Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.","Step:4 Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/BRImeP8.gif','https://static.exercisedb.dev/media/BRImeP8.gif',NULL),
('bRlbdjK','dumbbell decline shrug v. 2',NULL,'back','traps','{"shoulders","rhomboids"}','dumbbell',NULL,'{"Step:1 Set up a decline bench at a 45-degree angle.","Step:2 Lie face down on the bench with your chest and stomach resting on it.","Step:3 Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.","Step:4 Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.","Step:5 Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bRlbdjK.gif','https://static.exercisedb.dev/media/bRlbdjK.gif',NULL),
('bTpEUcm','barbell low bar squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and the barbell resting on your upper back.","Step:2 Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.","Step:3 Continue lowering until your thighs are parallel to the ground or slightly below.","Step:4 Pause for a moment, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bTpEUcm.gif','https://static.exercisedb.dev/media/bTpEUcm.gif',NULL),
('BU15nH4','dumbbell alternate biceps curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions, alternating arms."}','https://static.exercisedb.dev/media/BU15nH4.gif','https://static.exercisedb.dev/media/BU15nH4.gif',NULL),
('bWlZvXh','butterfly yoga pose',NULL,'legs','adductors','{"hamstrings","groin"}','body weight',NULL,'{"Step:1 Sit on the floor with your legs extended in front of you.","Step:2 Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.","Step:3 Hold onto your ankles or feet with your hands.","Step:4 Sit up tall and lengthen your spine.","Step:5 Gently press your knees down towards the floor, feeling a stretch in your inner thighs.","Step:6 Hold this position for a few breaths.","Step:7 To release, slowly bring your knees back up and extend your legs."}','https://static.exercisedb.dev/media/bWlZvXh.gif','https://static.exercisedb.dev/media/bWlZvXh.gif',NULL),
('BWnJR72','lying (side) quads stretch',NULL,'legs','quads','{"hamstrings"}','body weight',NULL,'{"Step:1 Lie on your side with your legs straight.","Step:2 Bend your top leg and grab your ankle or foot with your hand.","Step:3 Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.","Step:4 Hold the stretch for 20-30 seconds.","Step:5 Release the stretch and repeat on the other side."}','https://static.exercisedb.dev/media/BWnJR72.gif','https://static.exercisedb.dev/media/BWnJR72.gif',NULL),
('BwSNDGt','dumbbell one arm reverse wrist curl',NULL,'arms','forearms','{"wrist extensors"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground.","Step:2 Hold a dumbbell in one hand with an overhand grip, palm facing down.","Step:3 Rest your forearm on your thigh, with your wrist hanging off the edge.","Step:4 Slowly lower the dumbbell towards the ground by flexing your wrist.","Step:5 Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.","Step:6 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/BwSNDGt.gif','https://static.exercisedb.dev/media/BwSNDGt.gif',NULL),
('bWxq4op','dumbbell one arm reverse preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.","Step:2 Lower the dumbbell slowly until your arm is fully extended.","Step:3 Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.","Step:4 Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/bWxq4op.gif','https://static.exercisedb.dev/media/bWxq4op.gif',NULL),
('ByX0WxV','dumbbell incline hammer curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Step:2 Keep your back against the bench and your feet flat on the floor.","Step:3 While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ByX0WxV.gif','https://static.exercisedb.dev/media/ByX0WxV.gif',NULL),
('bZGHsAZ','inverted row',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Set up a bar at waist height or use a suspension trainer.","Step:2 Stand facing the bar or suspension trainer, with your feet shoulder-width apart.","Step:3 Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Lean back, keeping your body straight and your heels on the ground.","Step:5 Pull your chest towards the bar or handles, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower yourself back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bZGHsAZ.gif','https://static.exercisedb.dev/media/bZGHsAZ.gif',NULL),
('bZq4bwK','weighted tricep dips',NULL,'arms','triceps','{"chest","shoulders"}','other',NULL,'{"Step:1 Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Step:2 Slide your butt off the front of the bench with your legs extended in front of you.","Step:3 Keep your back close to the bench and your elbows slightly bent.","Step:4 Lower your body by bending your elbows until your upper arms are parallel to the floor.","Step:5 Push yourself back up to the starting position by straightening your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/bZq4bwK.gif','https://static.exercisedb.dev/media/bZq4bwK.gif',NULL),
('C0eCeEt','twisted leg raise',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended and your arms by your sides.","Step:2 Place your hands under your glutes for support.","Step:3 Engage your abs and lift both legs off the ground, keeping them straight.","Step:4 As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.","Step:5 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:6 Repeat the movement, this time twisting your hips to the other side.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/C0eCeEt.gif','https://static.exercisedb.dev/media/C0eCeEt.gif',NULL),
('C0MA9bC','dumbbell one arm bent-over row',NULL,'back','upper back','{"biceps","forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Step:3 Let the dumbbell hang straight down towards the floor, with your arm fully extended.","Step:4 Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/C0MA9bC.gif','https://static.exercisedb.dev/media/C0MA9bC.gif',NULL),
('c16nYGA','band one arm twisting chest press',NULL,'chest','pectorals','{"shoulders","triceps"}','resistance band',NULL,'{"Step:1 Attach the band to a sturdy anchor point at chest height.","Step:2 Stand with your side facing the anchor point and grab the band with one hand.","Step:3 Step away from the anchor point to create tension in the band.","Step:4 Position your feet shoulder-width apart and slightly bend your knees.","Step:5 Bring your hand holding the band across your body, towards the opposite shoulder.","Step:6 While maintaining tension in the band, push your hand forward and away from your body, extending your arm.","Step:7 Slowly return to the starting position and repeat for the desired number of repetitions.","Step:8 Switch sides and repeat the exercise with the other hand."}','https://static.exercisedb.dev/media/c16nYGA.gif','https://static.exercisedb.dev/media/c16nYGA.gif',NULL),
('C31LMnP','one leg squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Extend one leg forward, keeping it off the ground.","Step:3 Bend your standing leg and lower your body down as if sitting back into a chair.","Step:4 Keep your chest up and your back straight.","Step:5 Push through your heel to return to the starting position.","Step:6 Repeat with the other leg."}','https://static.exercisedb.dev/media/C31LMnP.gif','https://static.exercisedb.dev/media/C31LMnP.gif',NULL),
('c3Pfhti','roller side lat stretch',NULL,'back','lats','{"shoulders","triceps"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.","Step:4 Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/c3Pfhti.gif','https://static.exercisedb.dev/media/c3Pfhti.gif',NULL),
('c3QQLPi','cable rear drive',NULL,'arms','triceps','{"shoulders","back"}','cable',NULL,'{"Step:1 Attach a handle to a low pulley cable machine and stand facing away from the machine.","Step:2 Grasp the handle with an overhand grip and extend your arms straight out in front of you.","Step:3 Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.","Step:4 Slowly return the handle to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/c3QQLPi.gif','https://static.exercisedb.dev/media/c3QQLPi.gif',NULL),
('C5jncD2','standing single leg curl',NULL,'legs','hamstrings','{"glutes"}','body weight',NULL,'{"Step:1 Stand with your feet hip-width apart and your hands on your hips.","Step:2 Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.","Step:3 Slowly curl your right heel towards your glutes, squeezing your hamstring.","Step:4 Pause for a moment at the top, then slowly lower your right foot back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/C5jncD2.gif','https://static.exercisedb.dev/media/C5jncD2.gif',NULL),
('C8Crfa4','targeted style smith close-grip bench press',NULL,'arms','triceps','{"chest","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the bench with your feet flat on the ground.","Step:2 Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Step:3 Lower the barbell towards your chest, keeping your elbows close to your body. Focus on targeted movement.","Step:4 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/C8Crfa4.gif','https://static.exercisedb.dev/media/C8Crfa4.gif',NULL),
('c8f5cSY','side lying hip adduction (male)',NULL,'legs','adductors','{"glutes","hamstrings"}','body weight',NULL,'{"Step:1 Lie on your side with your legs straight and stacked on top of each other.","Step:2 Place your bottom arm under your head for support.","Step:3 Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.","Step:4 Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/c8f5cSY.gif','https://static.exercisedb.dev/media/c8f5cSY.gif',NULL),
('c8oybX6','cable rope elevated seated row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the elevated seat facing the cable machine.","Step:2 Grab the cable rope handles with an overhand grip, palms facing each other.","Step:3 Keep your back straight and lean slightly back, maintaining a slight bend in your knees.","Step:4 Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.","Step:5 Pause for a moment at the fully contracted position.","Step:6 Slowly release the tension and extend your arms back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/c8oybX6.gif','https://static.exercisedb.dev/media/c8oybX6.gif',NULL),
('C9LuR4A','lever donkey calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the leverage machine to the appropriate height for your body.","Step:2 Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.","Step:3 Place your hands on the handles or the support bars for stability.","Step:4 Engage your calves and lift your heels as high as possible, using the balls of your feet.","Step:5 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/C9LuR4A.gif','https://static.exercisedb.dev/media/C9LuR4A.gif',NULL),
('c9MnDRp','dumbbell raise',NULL,'shoulders','delts','{"traps","rhomboids"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Step:2 Keep your back straight and engage your core.","Step:3 Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/c9MnDRp.gif','https://static.exercisedb.dev/media/c9MnDRp.gif',NULL),
('Ca76jUE','kettlebell alternating row',NULL,'back','upper back','{"biceps","forearms"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Step:2 Bend forward at the hips, keeping your back straight and your core engaged.","Step:3 Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Step:4 Lower the kettlebell back down to the starting position and repeat with the other arm.","Step:5 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/Ca76jUE.gif','https://static.exercisedb.dev/media/Ca76jUE.gif',NULL),
('cA9FuWG','barbell bent arm pullover',NULL,'back','lats','{"triceps","chest"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your head at one end and your feet on the floor.","Step:2 Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Step:3 Lower the barbell behind your head while keeping your arms slightly bent.","Step:4 Pause for a moment, then raise the barbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/cA9FuWG.gif','https://static.exercisedb.dev/media/cA9FuWG.gif',NULL),
('cALkHHX','dumbbell iron cross',NULL,'shoulders','delts','{"triceps","chest"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Step:2 Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.","Step:3 Pause for a moment, then slowly lower your arms back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/cALkHHX.gif','https://static.exercisedb.dev/media/cALkHHX.gif',NULL),
('cALKspW','cable upright row',NULL,'shoulders','delts','{"traps","biceps"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.","Step:2 Keep your back straight and your core engaged throughout the exercise.","Step:3 Pull the cable attachment straight up towards your chin, leading with your elbows.","Step:4 Pause for a moment at the top, squeezing your shoulder blades together.","Step:5 Slowly lower the cable attachment back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/cALKspW.gif','https://static.exercisedb.dev/media/cALKspW.gif',NULL),
('cAvTaSg','dumbbell kickbacks on exercise ball',NULL,'arms','triceps','{"shoulders","back"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Step:3 Extend your arms straight back, squeezing your triceps at the top of the movement.","Step:4 Pause for a moment, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/cAvTaSg.gif','https://static.exercisedb.dev/media/cAvTaSg.gif',NULL),
('CB8WET1','incline push up depth jump',NULL,'chest','pectorals','{"triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.","Step:2 Step your feet back, keeping your body in a straight line from head to heels.","Step:3 Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.","Step:4 Push through your palms to extend your arms and return to the starting position.","Step:5 Jump off the edge of the surface, landing softly with your knees slightly bent.","Step:6 Repeat the push-up and depth jump for the desired number of repetitions."}','https://static.exercisedb.dev/media/CB8WET1.gif','https://static.exercisedb.dev/media/CB8WET1.gif',NULL),
('CbFSYC1','rear pull-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Step:2 Hang from the bar with your arms fully extended and your body straight.","Step:3 Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Step:4 Continue pulling until your chin is above the bar.","Step:5 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CbFSYC1.gif','https://static.exercisedb.dev/media/CbFSYC1.gif',NULL),
('cbuFJrn','lever gripless shrug v. 2',NULL,'back','traps','{"shoulders","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back against the pad.","Step:2 Grasp the handles or bars with an overhand grip, keeping your arms straight.","Step:3 Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Step:4 Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/cbuFJrn.gif','https://static.exercisedb.dev/media/cbuFJrn.gif',NULL),
('CcWEoWV','short stride run',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Find an open space or a treadmill to perform the exercise.","Step:2 Stand tall with your feet hip-width apart.","Step:3 Start jogging in place, lifting your knees high and pumping your arms.","Step:4 After a few seconds, start taking short strides forward, maintaining a quick pace.","Step:5 Continue running with short strides for the desired duration or distance."}','https://static.exercisedb.dev/media/CcWEoWV.gif','https://static.exercisedb.dev/media/CcWEoWV.gif',NULL),
('CfKsRbG','dumbbell alternate biceps curl (with arm blaster)',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Step:2 Place the arm blaster on your upper arms, ensuring a secure fit.","Step:3 Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.","Step:4 Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly lower the dumbbell back to the starting position.","Step:7 Repeat the movement with the opposite arm.","Step:8 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/CfKsRbG.gif','https://static.exercisedb.dev/media/CfKsRbG.gif',NULL),
('CFN9P8G','ez bar french press on exercise ball',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Sit on an exercise ball and hold an EZ barbell with an overhand grip.","Step:2 Extend your arms straight up, keeping your elbows close to your head.","Step:3 Slowly lower the barbell behind your head by bending your elbows.","Step:4 Pause for a moment, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CFN9P8G.gif','https://static.exercisedb.dev/media/CFN9P8G.gif',NULL),
('CggQhII','lever military press',NULL,'shoulders','delts','{"triceps","upper chest"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back against the backrest.","Step:2 Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Step:3 Push the handles upward until your arms are fully extended, but do not lock your elbows.","Step:4 Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CggQhII.gif','https://static.exercisedb.dev/media/CggQhII.gif',NULL),
('chfnQnM','back pec stretch',NULL,'back','lats','{"shoulders","chest"}','body weight',NULL,'{"Step:1 Stand tall with your feet shoulder-width apart.","Step:2 Extend your arms straight out in front of you, parallel to the ground.","Step:3 Cross your arms in front of your body, with your right arm over your left arm.","Step:4 Interlock your fingers and rotate your palms away from your body.","Step:5 Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.","Step:6 Hold the stretch for 15-30 seconds, then release.","Step:7 Repeat on the opposite side."}','https://static.exercisedb.dev/media/chfnQnM.gif','https://static.exercisedb.dev/media/chfnQnM.gif',NULL),
('CHpahtl','lever seated hip abduction',NULL,'legs','abductors','{"glutes","hamstrings"}','machine',NULL,'{"Step:1 Adjust the seat height so that your knees are at a 90-degree angle.","Step:2 Sit on the machine with your back against the backrest and your feet on the footrests.","Step:3 Place your hands on the side handles for stability.","Step:4 Engage your abductors and slowly push your legs apart, away from the midline of your body.","Step:5 Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CHpahtl.gif','https://static.exercisedb.dev/media/CHpahtl.gif',NULL),
('CI6baTY','bottoms-up',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended and your arms by your sides.","Step:2 Bend your knees and bring them towards your chest, keeping your feet off the ground.","Step:3 Engaging your abs, lift your hips off the ground, bringing your knees towards your head.","Step:4 Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CI6baTY.gif','https://static.exercisedb.dev/media/CI6baTY.gif',NULL),
('CjETvlw','roller seated single leg shoulder flexor depresor retractor',NULL,'chest','pectorals','{"deltoids","triceps"}','other',NULL,'{"Step:1 Sit on a flat surface with your legs extended in front of you.","Step:2 Hold the roller with both hands, palms facing down, and place it on your thighs.","Step:3 Lean back slightly and engage your core muscles.","Step:4 Raise the roller up to shoulder level, keeping your arms straight.","Step:5 Slowly lower the roller back down to your thighs.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CjETvlw.gif','https://static.exercisedb.dev/media/CjETvlw.gif',NULL),
('cJgSTmh','oblique crunch v. 2',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Lie on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head or cross them over your chest.","Step:3 Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.","Step:4 Pause for a moment, then lower your shoulder blades back down to the starting position.","Step:5 Repeat on the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/cJgSTmh.gif','https://static.exercisedb.dev/media/cJgSTmh.gif',NULL),
('CJwa0vD','dumbbell standing bent over one arm triceps extension',NULL,'arms','triceps','{"shoulders","back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Step:2 Bend forward at the waist, keeping your back straight and parallel to the ground.","Step:3 Extend your arm straight back, keeping your elbow close to your body.","Step:4 Slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/CJwa0vD.gif','https://static.exercisedb.dev/media/CJwa0vD.gif',NULL),
('CMAxnsG','clock push-up',NULL,'chest','pectorals','{"triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Step:3 As you lower, rotate your body to the left, extending your left arm straight out to the side.","Step:4 Push back up to the starting position, while rotating your body to the center.","Step:5 Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.","Step:6 Continue alternating sides with each repetition."}','https://static.exercisedb.dev/media/CMAxnsG.gif','https://static.exercisedb.dev/media/CMAxnsG.gif',NULL),
('CmEr4pM','cable wide grip rear pulldown behind neck',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Adjust the cable machine so that the pulldown bar is at a height above your head.","Step:2 Sit down on the seat and grab the pulldown bar with a wide overhand grip.","Step:3 Keep your back straight and your chest up as you lean back slightly.","Step:4 Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CmEr4pM.gif','https://static.exercisedb.dev/media/CmEr4pM.gif',NULL),
('CosupLu','front plank with twist',NULL,'core','abs','{"obliques","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Step:2 Engage your core and glutes to maintain a stable position.","Step:3 Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.","Step:4 Keep your hips and legs stable as you twist.","Step:5 Hold for a moment, then return to the starting position.","Step:6 Repeat the twist on the left side.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/CosupLu.gif','https://static.exercisedb.dev/media/CosupLu.gif',NULL),
('cQ19bBP','rocky pull-up pulldown',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Stand in front of a pull-up bar with your feet shoulder-width apart.","Step:2 Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Hang from the bar with your arms fully extended and your body straight.","Step:4 Engage your back muscles and pull your body up towards the bar, leading with your chest.","Step:5 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/cQ19bBP.gif','https://static.exercisedb.dev/media/cQ19bBP.gif',NULL),
('CQHoDm0','ez barbell decline triceps extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Lie on a decline bench with your head lower than your feet and your feet secured.","Step:2 Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Step:3 Extend your arms fully, keeping your elbows close to your head.","Step:4 Lower the barbell slowly towards your forehead, bending your elbows.","Step:5 Pause for a moment, then extend your arms back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CQHoDm0.gif','https://static.exercisedb.dev/media/CQHoDm0.gif',NULL),
('CqhoytW','smith hip raise',NULL,'core','abs','{"glutes","hamstrings"}','machine',NULL,'{"Step:1 Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.","Step:2 Place your hands on the barbell, slightly wider than shoulder-width apart.","Step:3 Engage your core and glutes, then push through your heels to raise your hips off the ground.","Step:4 Continue lifting until your body forms a straight line from your knees to your shoulders.","Step:5 Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CqhoytW.gif','https://static.exercisedb.dev/media/CqhoytW.gif',NULL),
('CuaWCmC','cable lateral pulldown (with rope attachment)',NULL,'back','lats','{"biceps","forearms"}','cable',NULL,'{"Step:1 Attach a rope attachment to the cable machine at a high position.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the rope with an overhand grip, palms facing each other.","Step:4 Keep your back straight and lean slightly back.","Step:5 Pull the rope down towards your sides, squeezing your shoulder blades together.","Step:6 Pause for a moment at the bottom of the movement.","Step:7 Slowly release the tension and allow the rope to return to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CuaWCmC.gif','https://static.exercisedb.dev/media/CuaWCmC.gif',NULL),
('cuC7529','one leg squat - expanded variation',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Extend one leg forward, keeping it off the ground.","Step:3 Bend your standing leg and lower your body down as if sitting back into a chair.","Step:4 Keep your chest up and your back straight.","Step:5 Push through your heel to return to the starting position.","Step:6 Repeat with the other leg. Maintain expanded form throughout."}','https://static.exercisedb.dev/media/cuC7529.gif','https://static.exercisedb.dev/media/cuC7529.gif',NULL),
('cuKYxhu','standing pelvic tilt',NULL,'back','spine','{"abdominals"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Place your hands on your hips or let them hang by your sides.","Step:3 Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.","Step:4 Hold the position for a few seconds, then release and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/cuKYxhu.gif','https://static.exercisedb.dev/media/cuKYxhu.gif',NULL),
('CUmLRTA','cable kneeling crunch - gentle variation',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Attach a rope handle to a high pulley and kneel down facing away from the machine.","Step:2 Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.","Step:3 Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.","Step:4 Pause for a moment at the bottom, then slowly return to the starting position. Maintain gentle form throughout.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CUmLRTA.gif','https://static.exercisedb.dev/media/CUmLRTA.gif',NULL),
('CvPn9WV','cable standing pulldown (with rope)',NULL,'arms','biceps','{"forearms","shoulders"}','cable',NULL,'{"Step:1 Attach a rope to the cable machine at the highest setting.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the rope with an overhand grip, palms facing down.","Step:4 Keep your back straight and core engaged throughout the exercise.","Step:5 Pull the rope down towards your thighs, squeezing your biceps.","Step:6 Pause for a moment at the bottom, then slowly release the rope back up.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/CvPn9WV.gif','https://static.exercisedb.dev/media/CvPn9WV.gif',NULL),
('cWemPG8','dumbbell prone incline hammer curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Adjust the bench to a 45-degree incline.","Step:2 Lie face down on the bench with a dumbbell in each hand, palms facing each other.","Step:3 Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.","Step:4 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:5 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:6 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:7 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/cWemPG8.gif','https://static.exercisedb.dev/media/cWemPG8.gif',NULL),
('cwsAI4G','dumbbell decline shrug',NULL,'back','traps','{"shoulders","rhomboids"}','dumbbell',NULL,'{"Step:1 Set up a decline bench at a 45-degree angle.","Step:2 Lie face down on the bench with your chest and stomach resting against it.","Step:3 Hold a dumbbell in each hand with your arms fully extended towards the floor.","Step:4 Keeping your arms straight, raise your shoulders towards your ears as high as possible.","Step:5 Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/cwsAI4G.gif','https://static.exercisedb.dev/media/cwsAI4G.gif',NULL),
('d1GgzTU','l-pull-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Step:2 Hang with your arms fully extended and your body straight.","Step:3 Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.","Step:4 Continue pulling until your chin is above the bar.","Step:5 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/d1GgzTU.gif','https://static.exercisedb.dev/media/d1GgzTU.gif',NULL),
('D1xYJAU','dumbbell over bench wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.","Step:2 Allow your wrists to hang over the edge of the bench.","Step:3 Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Step:4 Pause for a moment, then slowly lower your wrists back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/D1xYJAU.gif','https://static.exercisedb.dev/media/D1xYJAU.gif',NULL),
('d5bTEPV','band step-up',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','resistance band',NULL,'{"Step:1 Place a band around your thighs, just above your knees.","Step:2 Stand facing a step or platform with your feet hip-width apart.","Step:3 Step up onto the platform with your right foot, pushing through your heel.","Step:4 Extend your left leg behind you, keeping it straight.","Step:5 Lower your left foot back down to the ground.","Step:6 Repeat with your left foot stepping up onto the platform.","Step:7 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/d5bTEPV.gif','https://static.exercisedb.dev/media/d5bTEPV.gif',NULL),
('D5yqP2p','lever overhand triceps dip',NULL,'arms','triceps','{"chest","shoulders"}','machine',NULL,'{"Step:1 Adjust the machine to the appropriate height and secure your body in position.","Step:2 Grasp the handles with an overhand grip and position your body so that your arms are fully extended.","Step:3 Lower your body by bending your elbows, keeping your upper arms close to your sides.","Step:4 Continue lowering until your upper arms are parallel to the floor.","Step:5 Pause for a moment, then push yourself back up to the starting position by extending your elbows.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/D5yqP2p.gif','https://static.exercisedb.dev/media/D5yqP2p.gif',NULL),
('d7z1Y7V','exercise ball hug',NULL,'back','spine','{"shoulders","chest"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your back straight.","Step:2 Hold the stability ball with both hands, hugging it close to your chest.","Step:3 Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.","Step:4 Continue leaning back until you feel a stretch in your back muscles.","Step:5 Hold the position for a few seconds, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/d7z1Y7V.gif','https://static.exercisedb.dev/media/d7z1Y7V.gif',NULL),
('d960PgE','barbell seated good morning',NULL,'legs','glutes','{"hamstrings","lower back"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.","Step:2 Keep your back straight and your chest up.","Step:3 Slowly hinge forward at the hips, lowering your torso towards the ground.","Step:4 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/d960PgE.gif','https://static.exercisedb.dev/media/d960PgE.gif',NULL),
('D9qe7CM','pelvic tilt into bridge',NULL,'legs','glutes','{"hamstrings","core"}','body weight',NULL,'{"Step:1 Lie on your back with your knees bent and feet flat on the ground.","Step:2 Place your arms by your sides with your palms facing down.","Step:3 Engage your glutes and core muscles.","Step:4 Tilt your pelvis upward, lifting your hips off the ground.","Step:5 Hold the bridge position for a few seconds.","Step:6 Slowly lower your hips back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/D9qe7CM.gif','https://static.exercisedb.dev/media/D9qe7CM.gif',NULL),
('d9Xaxq6','cable russian twists (on stability ball)',NULL,'core','abs','{"obliques","lower back"}','cable',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Hold the cable handle with both hands and extend your arms straight out in front of you.","Step:3 Lean back slightly while keeping your back straight and your core engaged.","Step:4 Twist your torso to the right, bringing the cable handle towards your right hip.","Step:5 Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.","Step:6 Continue alternating twists for the desired number of repetitions."}','https://static.exercisedb.dev/media/d9Xaxq6.gif','https://static.exercisedb.dev/media/d9Xaxq6.gif',NULL),
('da4cXST','ez-bar close-grip bench press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.","Step:3 Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Step:4 Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Step:5 Pause for a moment when the barbell touches your chest.","Step:6 Push the barbell back up to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/da4cXST.gif','https://static.exercisedb.dev/media/da4cXST.gif',NULL),
('daBmy1Y','dumbbell single leg deadlift with stepbox support',NULL,'legs','glutes','{"hamstrings","lower back"}','dumbbell',NULL,'{"Step:1 Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Step:2 Place your left foot on a stepbox or elevated surface behind you.","Step:3 Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.","Step:4 As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.","Step:5 Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/daBmy1Y.gif','https://static.exercisedb.dev/media/daBmy1Y.gif',NULL),
('dAJscVq','cable incline bench row - elite variation',NULL,'back','upper back','{"biceps","rear deltoids"}','cable',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.","Step:2 Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.","Step:3 Grasp the cable handle with an overhand grip and extend your arms fully in front of you. Perform with elite intensity.","Step:4 Lean forward from your hips while keeping your back straight and your core engaged.","Step:5 Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.","Step:6 Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dAJscVq.gif','https://static.exercisedb.dev/media/dAJscVq.gif',NULL),
('dB07vDu','cable one arm lateral bent-over',NULL,'chest','pectorals','{"deltoids","trapezius"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart, facing a cable machine.","Step:2 Grasp the handle with one hand and step back to create tension on the cable.","Step:3 Bend forward at the waist, keeping your back straight and your core engaged.","Step:4 Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.","Step:5 Slowly bring your arm back to the starting position, maintaining control throughout the movement.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/dB07vDu.gif','https://static.exercisedb.dev/media/dB07vDu.gif',NULL),
('DB0n8AG','kettlebell front squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:2 Hold the kettlebell with both hands in front of your chest, close to your body.","Step:3 Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Step:4 Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Drive through your heels to stand back up, squeezing your glutes at the top.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DB0n8AG.gif','https://static.exercisedb.dev/media/DB0n8AG.gif',NULL),
('Db7eEgw','cable concentration extension (on knee)',NULL,'arms','triceps','{"forearms"}','cable',NULL,'{"Step:1 Sit on a bench or chair with your knees bent and feet flat on the ground.","Step:2 Hold the cable handle with your right hand and place your elbow on the inside of your right knee.","Step:3 Extend your arm fully, keeping your elbow stationary and close to your knee.","Step:4 Pause for a moment at the top, then slowly lower your arm back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/Db7eEgw.gif','https://static.exercisedb.dev/media/Db7eEgw.gif',NULL),
('dCJnuVq','medicine ball chest push from 3 point stance',NULL,'chest','pectorals','{"shoulders","triceps"}','medicine ball',NULL,'{"Step:1 Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.","Step:2 Extend your legs and position your body in a straight line.","Step:3 Lower your chest towards the ground while keeping your back straight.","Step:4 Push the medicine ball away from your body, extending your arm fully.","Step:5 Return to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dCJnuVq.gif','https://static.exercisedb.dev/media/dCJnuVq.gif',NULL),
('dCPESfR','barbell standing bradford press',NULL,'shoulders','delts','{"triceps","upper back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.","Step:2 Press the barbell overhead, fully extending your arms.","Step:3 Lower the barbell back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dCPESfR.gif','https://static.exercisedb.dev/media/dCPESfR.gif',NULL),
('DeDThfG','seated glute stretch',NULL,'legs','glutes','{"hamstrings"}','body weight',NULL,'{"Step:1 Sit on the ground with your legs extended in front of you.","Step:2 Bend your right knee and cross your right ankle over your left thigh.","Step:3 Place your right hand on the ground behind you for support.","Step:4 With your left hand, gently press down on your right knee to deepen the stretch.","Step:5 Hold the stretch for 30 seconds to 1 minute.","Step:6 Switch sides and repeat."}','https://static.exercisedb.dev/media/DeDThfG.gif','https://static.exercisedb.dev/media/DeDThfG.gif',NULL),
('DEEqoI2','posterior tibialis stretch',NULL,'legs','calves','{"hamstrings","quadriceps"}','other',NULL,'{"Step:1 Sit on the ground with your legs extended in front of you.","Step:2 Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Step:3 Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Step:4 Hold the stretch for 20-30 seconds.","Step:5 Release the tension on the rope and relax your foot.","Step:6 Repeat the stretch on the other leg."}','https://static.exercisedb.dev/media/DEEqoI2.gif','https://static.exercisedb.dev/media/DEEqoI2.gif',NULL),
('DFGXwZr','world greatest stretch',NULL,'legs','hamstrings','{"glutes","quadriceps","calves"}','body weight',NULL,'{"Step:1 Start in a lunge position with your right foot forward and your left foot back.","Step:2 Place your hands on the ground on either side of your right foot.","Step:3 Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.","Step:4 Rotate your torso to the right, reaching your right arm up towards the ceiling.","Step:5 Hold this position for a few seconds, then return to the starting position.","Step:6 Switch sides and repeat the stretch with your left foot forward."}','https://static.exercisedb.dev/media/DFGXwZr.gif','https://static.exercisedb.dev/media/DFGXwZr.gif',NULL),
('dFSNDOA','barbell seated twist',NULL,'core','abs','{"obliques","lower back"}','barbell',NULL,'{"Step:1 Sit on a flat bench with your feet flat on the ground and your knees bent.","Step:2 Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.","Step:3 Engage your core and slowly twist your torso to one side, keeping your back straight.","Step:4 Pause for a moment at the end of the twist, then slowly rotate back to the starting position.","Step:5 Repeat the twist to the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/dFSNDOA.gif','https://static.exercisedb.dev/media/dFSNDOA.gif',NULL),
('dG5Smob','snatch pull',NULL,'legs','quads','{"hamstrings","glutes","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Step:2 Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.","Step:3 Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","Step:4 As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","Step:5 As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.","Step:6 Catch the barbell overhead with your arms fully extended and your knees bent.","Step:7 Stand up by extending your hips and knees, keeping the barbell overhead.","Step:8 Lower the barbell back down to the starting position by reversing the movement.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dG5Smob.gif','https://static.exercisedb.dev/media/dG5Smob.gif',NULL),
('dG7tG5y','barbell shrug',NULL,'back','traps','{"shoulders"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.","Step:2 Keep your arms straight and your back straight throughout the exercise.","Step:3 Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.","Step:4 Hold for a moment, then slowly lower your shoulders back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dG7tG5y.gif','https://static.exercisedb.dev/media/dG7tG5y.gif',NULL),
('DgZQ11d','ez barbell decline close grip face press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Lie on a decline bench with your head lower than your feet.","Step:2 Grasp the ez barbell with a close grip, palms facing each other.","Step:3 Extend your arms straight up above your chest, keeping your elbows close to your body.","Step:4 Lower the barbell towards your forehead by bending your elbows.","Step:5 Pause for a moment, then press the barbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DgZQ11d.gif','https://static.exercisedb.dev/media/DgZQ11d.gif',NULL),
('DhMl549','barbell full squat (back pov)',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:2 Hold the barbell across your upper back, resting it on your traps or rear delts.","Step:3 Engage your core and keep your chest up as you begin to lower your body down.","Step:4 Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Step:5 Lower your body until your thighs are parallel to the ground or slightly below.","Step:6 Keep your knees in line with your toes and your weight in your heels.","Step:7 Drive through your heels to stand back up, extending your hips and knees.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DhMl549.gif','https://static.exercisedb.dev/media/DhMl549.gif',NULL),
('DICPHtq','targeted style single leg calf raise (on a dumbbell)',NULL,'legs','calves','{"ankles","feet"}','dumbbell',NULL,'{"Step:1 Stand with your feet hip-width apart and hold a dumbbell in one hand.","Step:2 Lift one foot off the ground and balance on the other foot.","Step:3 Slowly raise your heel as high as possible, using your calf muscles. Emphasize targeted control.","Step:4 Pause for a moment at the top, then slowly lower your heel back down.","Step:5 Repeat for the desired number of repetitions, then switch to the other leg."}','https://static.exercisedb.dev/media/DICPHtq.gif','https://static.exercisedb.dev/media/DICPHtq.gif',NULL),
('DIVyqrU','sphinx',NULL,'back','spine','{"glutes","hamstrings"}','body weight',NULL,'{"Step:1 Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Step:2 Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.","Step:3 Hold this position for a few seconds, making sure to keep your neck in a neutral position.","Step:4 Slowly lower your chest back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DIVyqrU.gif','https://static.exercisedb.dev/media/DIVyqrU.gif',NULL),
('dK9394r','burpee',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves","shoulders","chest"}','body weight',NULL,'{"Step:1 Start in a standing position with your feet shoulder-width apart.","Step:2 Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.","Step:3 Kick your feet back into a push-up position.","Step:4 Perform a push-up, keeping your body in a straight line.","Step:5 Jump your feet back into the squat position.","Step:6 Jump up explosively, reaching your arms overhead.","Step:7 Land softly and immediately lower back into a squat position to begin the next repetition."}','https://static.exercisedb.dev/media/dK9394r.gif','https://static.exercisedb.dev/media/dK9394r.gif',NULL),
('DKBwJrL','band one arm twisting seated row',NULL,'back','upper back','{"biceps","shoulders"}','resistance band',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground and your back straight.","Step:2 Hold the band with one hand and extend your arm fully in front of you.","Step:3 Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.","Step:4 At the same time, twist your torso towards the side of the pulling arm.","Step:5 Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/DKBwJrL.gif','https://static.exercisedb.dev/media/DKBwJrL.gif',NULL),
('dmgMp3n','barbell incline row',NULL,'back','upper back','{"biceps","forearms"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Lie face down on the bench with your chest against the pad and your feet flat on the ground.","Step:3 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Keep your back straight and your core engaged.","Step:5 Pull the barbell towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dmgMp3n.gif','https://static.exercisedb.dev/media/dmgMp3n.gif',NULL),
('dNFYIU1','lever shoulder press v. 3',NULL,'shoulders','delts','{"triceps","chest"}','machine',NULL,'{"Step:1 Adjust the seat height and backrest of the leverage machine to a comfortable position.","Step:2 Sit on the machine with your back against the backrest and your feet flat on the floor.","Step:3 Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Push the handles upward and forward until your arms are fully extended, but not locked.","Step:5 Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dNFYIU1.gif','https://static.exercisedb.dev/media/dNFYIU1.gif',NULL),
('DoEYq4s','sissy squat isolation',NULL,'legs','quads','{"calves","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Step:2 Hold onto a stable object for balance if needed.","Step:3 Slowly lower your body by bending your knees and leaning back, keeping your torso upright.","Step:4 Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.","Step:5 Pause for a moment, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions. Emphasize isolation control."}','https://static.exercisedb.dev/media/DoEYq4s.gif','https://static.exercisedb.dev/media/DoEYq4s.gif',NULL),
('DOoWcnA','lever chest press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back flat against the pad.","Step:2 Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Step:3 Push the handles forward until your arms are fully extended, exhaling during the movement.","Step:4 Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DOoWcnA.gif','https://static.exercisedb.dev/media/DOoWcnA.gif',NULL),
('DotAgEF','barbell reverse grip decline bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','barbell',NULL,'{"Step:1 Lie on a decline bench with your feet secured and your head lower than your hips.","Step:2 Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.","Step:3 Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Step:4 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DotAgEF.gif','https://static.exercisedb.dev/media/DotAgEF.gif',NULL),
('dPmaUaU','dumbbell standing calf raise',NULL,'legs','calves','{"ankles"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Step:2 Raise your heels off the ground as high as possible, using your calves.","Step:3 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dPmaUaU.gif','https://static.exercisedb.dev/media/dPmaUaU.gif',NULL),
('DptumMx','band close-grip pulldown',NULL,'back','lats','{"biceps","forearms"}','resistance band',NULL,'{"Step:1 Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Step:2 Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.","Step:3 Step back to create tension in the band, keeping your feet hip-width apart.","Step:4 Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DptumMx.gif','https://static.exercisedb.dev/media/DptumMx.gif',NULL),
('DpWMFP5','cable seated overhead curl',NULL,'arms','biceps','{"forearms","shoulders"}','cable',NULL,'{"Step:1 Sit on a bench facing the cable machine with your feet flat on the ground.","Step:2 Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Step:3 Keep your upper arms stationary and your elbows close to your sides.","Step:4 Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Step:5 Pause for a moment at the top of the movement, squeezing your biceps.","Step:6 Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DpWMFP5.gif','https://static.exercisedb.dev/media/DpWMFP5.gif',NULL),
('DQ0cqkT','three bench dip',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Sit on a bench with your hands gripping the edge, fingers pointing forward.","Step:2 Slide your butt off the bench, supporting your weight with your hands.","Step:3 Bend your elbows and lower your body until your upper arms are parallel to the ground.","Step:4 Push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DQ0cqkT.gif','https://static.exercisedb.dev/media/DQ0cqkT.gif',NULL),
('drfGhTV','balance cable incline fly',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Adjust the cable machine to a low position and attach the handles.","Step:2 Sit on an incline bench with your back against the pad and feet flat on the floor. Perform with balance intensity.","Step:3 Grasp the handles with an overhand grip and extend your arms straight out in front of you.","Step:4 Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Step:5 Pause for a moment at the fully extended position, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/drfGhTV.gif','https://static.exercisedb.dev/media/drfGhTV.gif',NULL),
('dRTfGZT','lever lateral raise',NULL,'shoulders','delts','{"traps","upper back"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back against the pad.","Step:2 Grasp the handles with an overhand grip and keep your arms straight.","Step:3 Exhale and raise your arms out to the sides until they are parallel to the floor.","Step:4 Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dRTfGZT.gif','https://static.exercisedb.dev/media/dRTfGZT.gif',NULL),
('Dsfz0Id','ez bar seated close grip concentration curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.","Step:2 Rest your elbow on the inside of your thigh, just above the knee.","Step:3 Curl the barbell up towards your shoulder while keeping your upper arm stationary.","Step:4 Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Dsfz0Id.gif','https://static.exercisedb.dev/media/Dsfz0Id.gif',NULL),
('DsgkuIt','dumbbell lateral raise',NULL,'shoulders','delts','{"traps"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Step:2 Keep your back straight and engage your core.","Step:3 Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DsgkuIt.gif','https://static.exercisedb.dev/media/DsgkuIt.gif',NULL),
('DT14T9T','cable straight arm pulldown (with rope)',NULL,'back','lats','{"biceps","forearms"}','cable',NULL,'{"Step:1 Attach a rope to the cable machine at the highest setting.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the rope with both hands, palms facing down.","Step:4 Extend your arms fully in front of you, keeping your elbows slightly bent.","Step:5 Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.","Step:6 Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DT14T9T.gif','https://static.exercisedb.dev/media/DT14T9T.gif',NULL),
('dTg95eZ','knee touch crunch',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.","Step:4 Return to the starting position and repeat, this time reaching your left hand towards your right knee.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/dTg95eZ.gif','https://static.exercisedb.dev/media/dTg95eZ.gif',NULL),
('DU5Kkj2','dumbbell standing one arm reverse curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.","Step:2 Keep your arm fully extended and close to your body, with your palm facing down.","Step:3 Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/DU5Kkj2.gif','https://static.exercisedb.dev/media/DU5Kkj2.gif',NULL),
('dU605di','cable pushdown (with rope attachment)',NULL,'arms','triceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a rope attachment to a high pulley on a cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Step:3 Grasp the rope with an overhand grip, palms facing each other.","Step:4 Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Step:5 Exhale and push the rope downward by extending your elbows until your arms are fully extended.","Step:6 Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dU605di.gif','https://static.exercisedb.dev/media/dU605di.gif',NULL),
('DU7I633','barbell reverse grip incline bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Lie down on the bench with your feet flat on the ground.","Step:3 Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Step:5 Pause for a moment when the barbell touches your chest.","Step:6 Push the barbell back up to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DU7I633.gif','https://static.exercisedb.dev/media/DU7I633.gif',NULL),
('dVeWXf2','chin-up diagonal',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Step:2 Engage your core and pull your body up towards the bar, leading with your chest.","Step:3 Continue pulling until your chin is above the bar.","Step:4 (diagonal variation) Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dVeWXf2.gif','https://static.exercisedb.dev/media/dVeWXf2.gif',NULL),
('DwhEmmE','dumbbell decline bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie down on a decline bench with your feet secured and your head lower than your hips.","Step:2 Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.","Step:3 Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Step:4 Push the dumbbells back up to the starting position, fully extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/DwhEmmE.gif','https://static.exercisedb.dev/media/DwhEmmE.gif',NULL),
('Dx2RIva','triple style sled one leg calf press on leg press',NULL,'legs','calves','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Step:2 Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.","Step:3 Place your toes and the balls of your feet on the sled, keeping your heels off.","Step:4 Push the sled forward by extending your ankles, keeping your knees slightly bent.","Step:5 Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.","Step:6 Repeat for the desired number of repetitions. Perform with triple intensity."}','https://static.exercisedb.dev/media/Dx2RIva.gif','https://static.exercisedb.dev/media/Dx2RIva.gif',NULL),
('dXz8zjF','cable drag curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Stand facing a cable machine with your feet shoulder-width apart.","Step:2 Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.","Step:4 Pause for a moment at the top of the movement, squeezing your biceps.","Step:5 Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dXz8zjF.gif','https://static.exercisedb.dev/media/dXz8zjF.gif',NULL),
('dZl9Q27','barbell standing overhead triceps extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.","Step:2 Raise the barbell overhead, fully extending your arms.","Step:3 Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Step:4 Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dZl9Q27.gif','https://static.exercisedb.dev/media/dZl9Q27.gif',NULL),
('dzz6BiV','smith sumo squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Set up the smith machine with the barbell at hip height.","Step:2 Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Step:3 Position yourself under the barbell, resting it on your upper back and shoulders.","Step:4 Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Step:5 Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:6 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/dzz6BiV.gif','https://static.exercisedb.dev/media/dzz6BiV.gif',NULL),
('e1e76I2','jump rope',NULL,'cardio','cardiovascular system','{"calves","quadriceps","hamstrings","glutes"}','other',NULL,'{"Step:1 Hold the handles of the jump rope with your hands, palms facing inward.","Step:2 Stand with your feet shoulder-width apart and knees slightly bent.","Step:3 Swing the rope over your head and jump over it as it comes towards your feet.","Step:4 Land softly on the balls of your feet and repeat the jump as the rope comes around again.","Step:5 Continue jumping for the desired duration or number of repetitions."}','https://static.exercisedb.dev/media/e1e76I2.gif','https://static.exercisedb.dev/media/e1e76I2.gif',NULL),
('e25F58f','dumbbell one arm reverse fly (with support)',NULL,'shoulders','delts','{"trapezius","rhomboids"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand with your palm facing inwards.","Step:3 Lean forward and place your free hand on the bench for support.","Step:4 Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.","Step:5 Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/e25F58f.gif','https://static.exercisedb.dev/media/e25F58f.gif',NULL),
('e4aFmFY','weighted front raise',NULL,'shoulders','delts','{"biceps","forearms"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Step:2 Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Step:3 Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/e4aFmFY.gif','https://static.exercisedb.dev/media/e4aFmFY.gif',NULL),
('e4ojVhP','dumbbell revers grip biceps curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/e4ojVhP.gif','https://static.exercisedb.dev/media/e4ojVhP.gif',NULL),
('E4PwJqI','self assisted inverse leg curl',NULL,'legs','hamstrings','{"glutes","calves"}','body weight',NULL,'{"Step:1 Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.","Step:2 Place your hands on the side handles of the machine for support.","Step:3 Keeping your upper body stationary, exhale and curl your legs upward as far as possible.","Step:4 Hold the contracted position for a brief pause as you squeeze your hamstrings.","Step:5 Slowly lower your legs back to the starting position while inhaling.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/E4PwJqI.gif','https://static.exercisedb.dev/media/E4PwJqI.gif',NULL),
('E4R8Hz1','band hip lift',NULL,'legs','glutes','{"hamstrings","quadriceps"}','resistance band',NULL,'{"Step:1 Lie on your back with your knees bent and feet flat on the ground.","Step:2 Place a resistance band just above your knees.","Step:3 Engage your glutes and core muscles.","Step:4 Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.","Step:5 Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/E4R8Hz1.gif','https://static.exercisedb.dev/media/E4R8Hz1.gif',NULL),
('ealLwvX','high knee against wall',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes","calves"}','body weight',NULL,'{"Step:1 Stand facing a wall with your feet hip-width apart.","Step:2 Place your hands on the wall for support.","Step:3 Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.","Step:4 Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.","Step:5 Continue alternating legs in a running motion, bringing your knees up as high as possible.","Step:6 Maintain a fast pace and keep your upper body stable throughout the exercise.","Step:7 Repeat for the desired duration or number of repetitions."}','https://static.exercisedb.dev/media/ealLwvX.gif','https://static.exercisedb.dev/media/ealLwvX.gif',NULL),
('EAs3xL9','dumbbell reverse fly',NULL,'shoulders','delts','{"trapezius","rhomboids"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Extend your arms straight down in front of you, palms facing each other.","Step:4 Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Step:5 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/EAs3xL9.gif','https://static.exercisedb.dev/media/EAs3xL9.gif',NULL),
('EcaV7aL','barbell lying close-grip press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.","Step:3 Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Step:4 Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Step:5 Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/EcaV7aL.gif','https://static.exercisedb.dev/media/EcaV7aL.gif',NULL),
('echClj7','barbell squat (on knees) with pure',NULL,'legs','quads','{"glutes","hamstrings","calves"}','barbell',NULL,'{"Step:1 Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.","Step:2 Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.","Step:3 Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight. Perform with pure intensity.","Step:4 Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/echClj7.gif','https://static.exercisedb.dev/media/echClj7.gif',NULL),
('ecl28tP','dumbbell contralateral forward lunge',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Step:2 Take a step forward with your right foot, keeping your back straight and core engaged.","Step:3 Lower your body by bending both knees until your right thigh is parallel to the ground.","Step:4 Push through your right heel to return to the starting position.","Step:5 Repeat with your left leg.","Step:6 Alternate legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/ecl28tP.gif','https://static.exercisedb.dev/media/ecl28tP.gif',NULL),
('ecpY0rH','reverse grip machine lat pulldown',NULL,'back','lats','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Step:2 Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Step:3 Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Step:4 Pull the handles down towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ecpY0rH.gif','https://static.exercisedb.dev/media/ecpY0rH.gif',NULL),
('Eg98Ft9','cable shrug',NULL,'back','traps','{"shoulders"}','cable',NULL,'{"Step:1 Stand facing the cable machine with your feet shoulder-width apart.","Step:2 Grasp the cable handles with an overhand grip and let your arms hang down in front of you.","Step:3 Keeping your arms straight, shrug your shoulders up towards your ears.","Step:4 Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Eg98Ft9.gif','https://static.exercisedb.dev/media/Eg98Ft9.gif',NULL),
('eGDudUV','cable deadlift',NULL,'legs','glutes','{"hamstrings","quadriceps","lower back"}','cable',NULL,'{"Step:1 Stand facing the cable machine with your feet shoulder-width apart.","Step:2 Bend at the hips and knees, lowering your torso until your back is parallel to the ground.","Step:3 Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.","Step:4 Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.","Step:5 Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eGDudUV.gif','https://static.exercisedb.dev/media/eGDudUV.gif',NULL),
('Eh2v5Iu','scissor jumps (male)',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Jump off the ground and simultaneously cross your right leg in front of your left leg.","Step:3 As you land, quickly switch legs, crossing your left leg in front of your right leg.","Step:4 Continue alternating legs and jumping as quickly as possible.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Eh2v5Iu.gif','https://static.exercisedb.dev/media/Eh2v5Iu.gif',NULL),
('eHBlPsa','cable one arm preacher curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Adjust the cable machine so that the preacher curl pad is at chest height.","Step:2 Stand facing the cable machine with your feet shoulder-width apart.","Step:3 Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.","Step:4 Keep your back straight and your core engaged.","Step:5 Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.","Step:6 Pause for a moment at the top of the movement, squeezing your biceps.","Step:7 Slowly lower the cable handle back to the starting position.","Step:8 Repeat for the desired number of repetitions.","Step:9 Switch arms and repeat the exercise."}','https://static.exercisedb.dev/media/eHBlPsa.gif','https://static.exercisedb.dev/media/eHBlPsa.gif',NULL),
('EIeI8Vf','barbell bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Step:3 Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Step:4 Lower the barbell slowly towards your chest, keeping your elbows tucked in.","Step:5 Pause for a moment when the barbell touches your chest.","Step:6 Push the barbell back up to the starting position by extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/EIeI8Vf.gif','https://static.exercisedb.dev/media/EIeI8Vf.gif',NULL),
('EIsE3u8','cable one arm bent over row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Stand facing a cable machine with your feet shoulder-width apart.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.","Step:4 Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.","Step:5 Pause for a moment, then slowly extend your arm back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/EIsE3u8.gif','https://static.exercisedb.dev/media/EIsE3u8.gif',NULL),
('EKXOMEh','dumbbell rear delt row_shoulder',NULL,'shoulders','delts','{"trapezius","rhomboids"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold a dumbbell in each hand with your palms facing your body.","Step:3 Bend forward at the waist, keeping your back straight and your core engaged.","Step:4 Extend your arms straight down towards the floor, with a slight bend in your elbows.","Step:5 Raise the dumbbells out to the sides, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/EKXOMEh.gif','https://static.exercisedb.dev/media/EKXOMEh.gif',NULL),
('elhhVgj','barbell narrow stance squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and toes pointing slightly outward.","Step:2 Hold the barbell across your upper back, resting it on your traps or rear delts.","Step:3 Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.","Step:4 Continue lowering until your thighs are parallel to the ground or slightly below.","Step:5 Pause for a moment, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/elhhVgj.gif','https://static.exercisedb.dev/media/elhhVgj.gif',NULL),
('EmlJR2y','dumbbell standing one arm curl over incline bench',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Step:2 Place your other hand on an incline bench for support.","Step:3 Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/EmlJR2y.gif','https://static.exercisedb.dev/media/EmlJR2y.gif',NULL),
('EMpUwRI','barbell lying extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Step:3 Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Step:4 Pause for a moment, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/EMpUwRI.gif','https://static.exercisedb.dev/media/EMpUwRI.gif',NULL),
('en550rk','dumbbell seated kickback',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and lean forward from your hips, keeping your back straight.","Step:3 Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.","Step:4 Extend your arms straight back, squeezing your triceps at the top of the movement.","Step:5 Pause for a moment, then slowly lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/en550rk.gif','https://static.exercisedb.dev/media/en550rk.gif',NULL),
('EnPivTL','barbell bent arm pullover - powerful variation',NULL,'back','lats','{"triceps","chest"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your head at one end and your feet on the floor.","Step:2 Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Step:3 Lower the barbell behind your head while keeping your arms slightly bent.","Step:4 Pause for a moment, then raise the barbell back to the starting position.","Step:5 Repeat for the desired number of repetitions. Focus on powerful movement."}','https://static.exercisedb.dev/media/EnPivTL.gif','https://static.exercisedb.dev/media/EnPivTL.gif',NULL),
('enxnJcM','quarter sit-up',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/enxnJcM.gif','https://static.exercisedb.dev/media/enxnJcM.gif',NULL),
('eOCOwIR','dumbbell lying elbow press',NULL,'arms','triceps','{"chest","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.","Step:2 Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.","Step:3 Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eOCOwIR.gif','https://static.exercisedb.dev/media/eOCOwIR.gif',NULL),
('eOG0r6v','cable reverse curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a straight bar to a low pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Step:3 Grasp the bar with an underhand grip, hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Step:5 Exhale and curl the bar up towards your shoulders, contracting your biceps.","Step:6 Pause for a moment at the top, squeezing your biceps.","Step:7 Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eOG0r6v.gif','https://static.exercisedb.dev/media/eOG0r6v.gif',NULL),
('eOrFCnx','dumbbell arnold press v. 2',NULL,'shoulders','delts','{"triceps","upper chest"}','dumbbell',NULL,'{"Step:1 Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Step:2 Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Step:3 Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eOrFCnx.gif','https://static.exercisedb.dev/media/eOrFCnx.gif',NULL),
('EpKrFiv','incline push up depth jump with complex',NULL,'chest','pectorals','{"triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.","Step:2 Step your feet back, keeping your body in a straight line from head to heels.","Step:3 Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned. Maintain complex form throughout.","Step:4 Push through your palms to extend your arms and return to the starting position.","Step:5 Jump off the edge of the surface, landing softly with your knees slightly bent.","Step:6 Repeat the push-up and depth jump for the desired number of repetitions."}','https://static.exercisedb.dev/media/EpKrFiv.gif','https://static.exercisedb.dev/media/EpKrFiv.gif',NULL),
('epOSYUZ','modified hindu push-up (male)',NULL,'chest','pectorals','{"triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.","Step:2 Lower your body towards the ground, bending your elbows and keeping your core engaged.","Step:3 As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.","Step:4 Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/epOSYUZ.gif','https://static.exercisedb.dev/media/epOSYUZ.gif',NULL),
('EqHIIjJ','barbell reverse preacher curl inclined',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.","Step:2 Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Step:3 Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Perform with inclined intensity.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/EqHIIjJ.gif','https://static.exercisedb.dev/media/EqHIIjJ.gif',NULL),
('ErqK3UL','posterior step to overhead reach',NULL,'core','abs','{"glutes","hamstrings","quadriceps","shoulders"}','body weight',NULL,'{"Step:1 Stand with your feet hip-width apart and your arms by your sides.","Step:2 Take a step back with your right foot, landing on the ball of your foot.","Step:3 Bend your left knee and lower your body into a lunge position.","Step:4 As you lower into the lunge, simultaneously reach your arms overhead.","Step:5 Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.","Step:6 Repeat the movement on the other side, stepping back with your left foot and bending your right knee.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/ErqK3UL.gif','https://static.exercisedb.dev/media/ErqK3UL.gif',NULL),
('ESOd5Pl','dumbbell incline fly',NULL,'chest','pectorals','{"shoulders"}','dumbbell',NULL,'{"Step:1 Set an incline bench to a 45-degree angle.","Step:2 Sit on the bench with a dumbbell in each hand, palms facing each other.","Step:3 Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.","Step:4 Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Step:5 Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ESOd5Pl.gif','https://static.exercisedb.dev/media/ESOd5Pl.gif',NULL),
('ETZfAbZ','smith decline bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the decline bench to the desired angle.","Step:2 Lie down on the bench with your feet secured under the foot pads.","Step:3 Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Step:5 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ETZfAbZ.gif','https://static.exercisedb.dev/media/ETZfAbZ.gif',NULL),
('euI1BwR','barbell speed squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:2 Hold the barbell across your upper back, resting it on your traps or rear delts.","Step:3 Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.","Step:4 Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Drive through your heels to stand back up, squeezing your glutes at the top.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/euI1BwR.gif','https://static.exercisedb.dev/media/euI1BwR.gif',NULL),
('euq4pwp','band standing twisting crunch',NULL,'core','abs','{"obliques"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.","Step:2 Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.","Step:3 Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.","Step:4 Pause for a moment, then return to the starting position.","Step:5 Repeat on the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/euq4pwp.gif','https://static.exercisedb.dev/media/euq4pwp.gif',NULL),
('eVxAzgz','incline leg hip raise (leg straight)',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.","Step:2 Place your hands on the sides of the bench for support.","Step:3 Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eVxAzgz.gif','https://static.exercisedb.dev/media/eVxAzgz.gif',NULL),
('eXFXCY0','lever seated crunch v. 2',NULL,'core','abs','{"obliques","hip flexors"}','machine',NULL,'{"Step:1 Sit on the leverage machine with your back against the pad and your feet secured under the footpads.","Step:2 Place your hands on the handles or the sides of the seat for support.","Step:3 Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Step:4 Pause for a moment at the top of the movement, squeezing your abs.","Step:5 Slowly return to the starting position, allowing your back to round slightly.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eXFXCY0.gif','https://static.exercisedb.dev/media/eXFXCY0.gif',NULL),
('eXMFHww','landmine lateral raise',NULL,'shoulders','delts','{"traps","upper back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold the barbell with an overhand grip, resting it on the front of your shoulders.","Step:3 Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.","Step:4 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eXMFHww.gif','https://static.exercisedb.dev/media/eXMFHww.gif',NULL),
('EyLrNC2','exercise ball alternating arm ups',NULL,'back','lats','{"shoulders","core"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.","Step:3 Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.","Step:4 Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Step:5 Repeat the movement with the other arm.","Step:6 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/EyLrNC2.gif','https://static.exercisedb.dev/media/EyLrNC2.gif',NULL),
('eYmsEPR','cable reverse wrist curl',NULL,'arms','forearms','{"forearms","wrists"}','cable',NULL,'{"Step:1 Attach a cable to a low pulley and sit on a bench facing the cable machine.","Step:2 Grasp the cable handle with an overhand grip, palms facing down.","Step:3 Rest your forearms on your thighs, with your wrists hanging off the edge.","Step:4 Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Step:5 Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eYmsEPR.gif','https://static.exercisedb.dev/media/eYmsEPR.gif',NULL),
('eYnzaCm','cable bar lateral pulldown',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Adjust the cable pulley to a high position and attach a straight bar.","Step:2 Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.","Step:3 Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Step:5 Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Step:6 Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eYnzaCm.gif','https://static.exercisedb.dev/media/eYnzaCm.gif',NULL),
('eZ79rbI','cable kneeling rear delt row (with rope) (male) expanded',NULL,'shoulders','delts','{"trapezius","rhomboids","biceps"}','cable',NULL,'{"Step:1 Attach a rope handle to a low cable pulley and kneel down facing the machine.","Step:2 (expanded variation) Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.","Step:3 Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.","Step:4 Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.","Step:5 Slowly release the tension and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eZ79rbI.gif','https://static.exercisedb.dev/media/eZ79rbI.gif',NULL),
('EZeDVzO','weighted decline sit-up',NULL,'core','abs','{"hip flexors","lower back"}','other',NULL,'{"Step:1 Lie flat on a decline bench with your feet secured under the foot pads.","Step:2 Place your hands behind your head or across your chest.","Step:3 Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/EZeDVzO.gif','https://static.exercisedb.dev/media/EZeDVzO.gif',NULL),
('Ezpnw9d','band reverse wrist curl',NULL,'arms','forearms','{"forearms"}','resistance band',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground.","Step:2 Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.","Step:3 Rest your forearms on your thighs, with your wrists hanging off the edge.","Step:4 Slowly curl your wrists upward, squeezing your forearms.","Step:5 Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Ezpnw9d.gif','https://static.exercisedb.dev/media/Ezpnw9d.gif',NULL),
('ezTvXcr','ring dips',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Start by hanging from the rings with your arms fully extended and your body straight.","Step:2 Lower your body by bending your elbows until your shoulders are below your elbows.","Step:3 Push yourself back up to the starting position by straightening your arms.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ezTvXcr.gif','https://static.exercisedb.dev/media/ezTvXcr.gif',NULL),
('eZyBC3j','barbell bent over row',NULL,'back','upper back','{"biceps","forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Bend forward at the hips while keeping your back straight and chest up.","Step:3 Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:4 Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.","Step:5 Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/eZyBC3j.gif','https://static.exercisedb.dev/media/eZyBC3j.gif',NULL),
('f1jf47L','dumbbell seated shoulder press (parallel grip)',NULL,'shoulders','delts','{"triceps","upper back"}','dumbbell',NULL,'{"Step:1 Sit on a bench with a dumbbell in each hand, palms facing inward.","Step:2 Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Step:3 Press the dumbbells upward until your arms are fully extended overhead.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/f1jf47L.gif','https://static.exercisedb.dev/media/f1jf47L.gif',NULL),
('F1KxjBa','dumbbell peacher hammer curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your torso.","Step:2 Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","Step:3 This will be your starting position.","Step:4 Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:5 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:6 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:7 Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Step:8 Repeat for the recommended amount of repetitions."}','https://static.exercisedb.dev/media/F1KxjBa.gif','https://static.exercisedb.dev/media/F1KxjBa.gif',NULL),
('f38OEuO','kneeling lat stretch',NULL,'back','lats','{"shoulders","triceps"}','body weight',NULL,'{"Step:1 Kneel on the ground with your knees hip-width apart and your toes pointing back.","Step:2 Extend your arms overhead and interlace your fingers.","Step:3 Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.","Step:4 Hold the stretch for 20-30 seconds, then return to the starting position.","Step:5 Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/f38OEuO.gif','https://static.exercisedb.dev/media/f38OEuO.gif',NULL),
('F3xgbjF','dumbbell incline biceps curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/F3xgbjF.gif','https://static.exercisedb.dev/media/F3xgbjF.gif',NULL),
('f4xtKBj','assisted standing pull-up',NULL,'back','lats','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the machine to your desired weight and height settings.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Engage your lats and biceps, and pull yourself up towards the handles.","Step:5 Pause for a moment at the top, squeezing your back muscles.","Step:6 Slowly lower yourself back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/f4xtKBj.gif','https://static.exercisedb.dev/media/f4xtKBj.gif',NULL),
('F56Xpw3','fierce weighted straight bar dip',NULL,'chest','pectorals','{"triceps","shoulders"}','other',NULL,'{"Step:1 Position yourself between parallel bars with your arms fully extended and your body straight.","Step:2 Lower your body by bending your elbows until your upper arms are parallel to the ground.","Step:3 Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Step:4 (fierce variation) Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/F56Xpw3.gif','https://static.exercisedb.dev/media/F56Xpw3.gif',NULL),
('f7fnAIB','cable squat row (with rope attachment)',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Attach a rope to a cable machine at waist height.","Step:2 Stand facing the cable machine with your feet shoulder-width apart.","Step:3 Bend your knees and lower your body into a squat position, keeping your back straight and chest up.","Step:4 Grasp the rope with an overhand grip, with your hands shoulder-width apart.","Step:5 Engage your core and pull the rope towards your body, squeezing your shoulder blades together.","Step:6 Keep your elbows close to your body and continue pulling until your hands reach your chest.","Step:7 Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/f7fnAIB.gif','https://static.exercisedb.dev/media/f7fnAIB.gif',NULL),
('F7vjXqT','incline push-up (on box)',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.","Step:2 Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Step:3 Lower your chest towards the box by bending your elbows, keeping your body in a straight line.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/F7vjXqT.gif','https://static.exercisedb.dev/media/F7vjXqT.gif',NULL),
('f7Y9eDZ','barbell thruster',NULL,'shoulders','delts','{"quadriceps","glutes","hamstrings","core"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.","Step:2 Lower into a squat position by bending your knees and pushing your hips back.","Step:3 As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.","Step:4 Lower the barbell back to shoulder height as you lower back into the squat position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/f7Y9eDZ.gif','https://static.exercisedb.dev/media/f7Y9eDZ.gif',NULL),
('f91FwXG','lever gripless shrug',NULL,'back','traps','{"shoulders","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the leverage machine.","Step:2 Grasp the handles with your palms facing inwards and your arms fully extended.","Step:3 Keeping your back straight, exhale and elevate your shoulders as high as possible.","Step:4 Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/f91FwXG.gif','https://static.exercisedb.dev/media/f91FwXG.gif',NULL),
('f9lVSSI','astride jumps (male)',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Bend your knees and lower your body into a squat position.","Step:3 Jump explosively upwards, extending your legs and arms.","Step:4 While in the air, spread your legs apart and bring your arms out to the sides.","Step:5 Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/f9lVSSI.gif','https://static.exercisedb.dev/media/f9lVSSI.gif',NULL),
('faHKVkK','barbell standing wide grip biceps curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.","Step:2 Keep your back straight and your elbows close to your torso.","Step:3 Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/faHKVkK.gif','https://static.exercisedb.dev/media/faHKVkK.gif',NULL),
('FAoIFMw','one arm dip',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Stand facing away from a bench or chair, with your feet shoulder-width apart.","Step:2 Place one hand on the bench or chair behind you, fingers pointing towards your body.","Step:3 Extend your legs out in front of you, keeping your heels on the ground.","Step:4 Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.","Step:5 Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."}','https://static.exercisedb.dev/media/FAoIFMw.gif','https://static.exercisedb.dev/media/FAoIFMw.gif',NULL),
('fBnPpzd','flexible assisted prone hamstring',NULL,'legs','hamstrings','{"glutes","lower back"}','other',NULL,'{"Step:1 Lie face down on a mat or bench with your legs fully extended.","Step:2 (flexible variation) Have a partner or use a resistance band to secure your ankles.","Step:3 Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/fBnPpzd.gif','https://static.exercisedb.dev/media/fBnPpzd.gif',NULL),
('Ff18ItA','weighted straight bar dip',NULL,'chest','pectorals','{"triceps","shoulders"}','other',NULL,'{"Step:1 Position yourself between parallel bars with your arms fully extended and your body straight.","Step:2 Lower your body by bending your elbows until your upper arms are parallel to the ground.","Step:3 Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Ff18ItA.gif','https://static.exercisedb.dev/media/Ff18ItA.gif',NULL),
('fF6GKVh','chair leg extended stretch with modified',NULL,'legs','quads','{"hamstrings","calves"}','body weight',NULL,'{"Step:1 Sit on the edge of a chair with your back straight and feet flat on the ground.","Step:2 Extend one leg straight out in front of you, keeping your heel on the ground.","Step:3 Lean forward slightly, feeling a stretch in your quadriceps.","Step:4 Hold this position for 20-30 seconds. Focus on modified movement.","Step:5 Switch legs and repeat the stretch."}','https://static.exercisedb.dev/media/fF6GKVh.gif','https://static.exercisedb.dev/media/fF6GKVh.gif',NULL),
('ffQsyBj','dumbbell one arm standing curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.","Step:2 Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.","Step:3 Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/ffQsyBj.gif','https://static.exercisedb.dev/media/ffQsyBj.gif',NULL),
('FFRP97T','frog crunch',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/FFRP97T.gif','https://static.exercisedb.dev/media/FFRP97T.gif',NULL),
('fgc9Xdl','cable standing one leg calf raise',NULL,'legs','calves','{"ankles","feet"}','cable',NULL,'{"Step:1 Stand facing a cable machine with your feet shoulder-width apart.","Step:2 Hold onto the cable machine for support.","Step:3 Lift one leg off the ground and balance on the other leg.","Step:4 Slowly raise your heel off the ground, lifting your body up onto your toes.","Step:5 Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/fgc9Xdl.gif','https://static.exercisedb.dev/media/fgc9Xdl.gif',NULL),
('Fhdtwf3','lever one arm bent over row',NULL,'back','upper back','{"biceps","forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.","Step:2 Bend forward at the hips, keeping your back straight and your head up.","Step:3 Let the barbell hang in front of you with your arms fully extended.","Step:4 Pull the barbell up towards your chest, keeping your elbows close to your body.","Step:5 Squeeze your shoulder blades together at the top of the movement.","Step:6 Lower the barbell back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Fhdtwf3.gif','https://static.exercisedb.dev/media/Fhdtwf3.gif',NULL),
('fhZQPlV','cable twist (up-down)',NULL,'core','abs','{"obliques","lower back"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart, facing the cable machine.","Step:2 Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Step:3 Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.","Step:4 Pause for a moment at the end of the rotation, then slowly return to the starting position.","Step:5 Repeat the rotation to the opposite side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/fhZQPlV.gif','https://static.exercisedb.dev/media/fhZQPlV.gif',NULL),
('fI18Rbc','barbell upright row v. 3',NULL,'shoulders','delts','{"traps","biceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:2 Let the barbell hang in front of your thighs, arms fully extended.","Step:3 Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.","Step:4 Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/fI18Rbc.gif','https://static.exercisedb.dev/media/fI18Rbc.gif',NULL),
('fjjY3N4','inverted style inverse leg curl (on pull-up cable machine)',NULL,'legs','hamstrings','{"glutes","calves"}','body weight',NULL,'{"Step:1 Adjust the cable machine so that the ankle straps are at the lowest setting.","Step:2 Lie face down on the bench with your legs extended and the ankle straps attached to your feet.","Step:3 Hold onto the handles of the bench for stability.","Step:4 Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.","Step:5 Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.","Step:6 Repeat for the desired number of repetitions. Maintain inverted form throughout."}','https://static.exercisedb.dev/media/fjjY3N4.gif','https://static.exercisedb.dev/media/fjjY3N4.gif',NULL),
('FkBIE6a','dumbbell lying femoral',NULL,'legs','hamstrings','{"glutes"}','dumbbell',NULL,'{"Step:1 Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.","Step:2 Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.","Step:3 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/FkBIE6a.gif','https://static.exercisedb.dev/media/FkBIE6a.gif',NULL),
('fKZgDEO','single leg calf raise (on a dumbbell)',NULL,'legs','calves','{"ankles","feet"}','dumbbell',NULL,'{"Step:1 Stand with your feet hip-width apart and hold a dumbbell in one hand.","Step:2 Lift one foot off the ground and balance on the other foot.","Step:3 Slowly raise your heel as high as possible, using your calf muscles.","Step:4 Pause for a moment at the top, then slowly lower your heel back down.","Step:5 Repeat for the desired number of repetitions, then switch to the other leg."}','https://static.exercisedb.dev/media/fKZgDEO.gif','https://static.exercisedb.dev/media/fKZgDEO.gif',NULL),
('fNGumX0','back and forth step',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Step forward with your right foot, bending your knee and lowering your body into a lunge position.","Step:3 Push off with your right foot and step back to the starting position.","Step:4 Repeat the movement with your left foot, alternating legs with each step.","Step:5 Continue stepping back and forth, maintaining a steady pace.","Step:6 Repeat for the desired duration or number of repetitions."}','https://static.exercisedb.dev/media/fNGumX0.gif','https://static.exercisedb.dev/media/fNGumX0.gif',NULL),
('fprd84i','ez barbell anti gravity press',NULL,'shoulders','delts','{"triceps","chest"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.","Step:2 Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.","Step:3 Press the barbell overhead, extending your arms fully.","Step:4 Lower the barbell back to shoulder height and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/fprd84i.gif','https://static.exercisedb.dev/media/fprd84i.gif',NULL),
('FQXdXzY','dumbbells seated triceps extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell in both hands with an overhand grip, and raise it above your head.","Step:3 Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Step:4 Extend your arms and raise the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/FQXdXzY.gif','https://static.exercisedb.dev/media/FQXdXzY.gif',NULL),
('FS63wTN','dumbbell push press',NULL,'shoulders','delts','{"triceps","core"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.","Step:2 Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.","Step:3 Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/FS63wTN.gif','https://static.exercisedb.dev/media/FS63wTN.gif',NULL),
('FSD6PGL','dumbbell pullover on exercise ball',NULL,'chest','pectorals','{"triceps","latissimus dorsi"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.","Step:2 Slowly lower the dumbbell behind your head while keeping your arms straight.","Step:3 Pause for a moment, then raise the dumbbell back to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/FSD6PGL.gif','https://static.exercisedb.dev/media/FSD6PGL.gif',NULL),
('FSF9WOs','wide-grip chest dip on high parallel bars - low variation',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.","Step:2 Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Step:3 (low variation) Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/FSF9WOs.gif','https://static.exercisedb.dev/media/FSF9WOs.gif',NULL),
('fSrPP6B','triceps press',NULL,'arms','triceps','{"shoulders"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Extend your arms straight out in front of you, parallel to the ground.","Step:3 Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/fSrPP6B.gif','https://static.exercisedb.dev/media/fSrPP6B.gif',NULL),
('fTlkJop','dumbbell side lying one hand raise',NULL,'shoulders','delts','{"trapezius","rhomboids"}','dumbbell',NULL,'{"Step:1 Lie on your side with your legs extended and your head supported by your arm.","Step:2 Hold a dumbbell in your top hand with your palm facing down.","Step:3 Keeping your arm straight, raise the dumbbell up to shoulder height.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/fTlkJop.gif','https://static.exercisedb.dev/media/fTlkJop.gif',NULL),
('fUBheHs','cable seated row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Step:2 Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.","Step:3 Pull the handles towards your body, squeezing your shoulder blades together.","Step:4 Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/fUBheHs.gif','https://static.exercisedb.dev/media/fUBheHs.gif',NULL),
('FVM1AUZ','lever t-bar reverse grip row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Step:2 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Keep your back straight and engage your core.","Step:4 Pull the handles towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/FVM1AUZ.gif','https://static.exercisedb.dev/media/FVM1AUZ.gif',NULL),
('FVmZVhk','cable low fly',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Attach the handles to the low pulleys of a cable machine and select an appropriate weight.","Step:2 Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.","Step:3 Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.","Step:4 Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.","Step:5 Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.","Step:6 Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/FVmZVhk.gif','https://static.exercisedb.dev/media/FVmZVhk.gif',NULL),
('FWdVhcW','cable standing shoulder external rotation',NULL,'shoulders','delts','{"rotator cuff","trapezius"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Hold the cable handle with your arm extended in front of you, parallel to the ground.","Step:3 Keep your elbow slightly bent and your shoulder blades pulled back.","Step:4 Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.","Step:5 Pause for a moment at the end of the movement, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/FWdVhcW.gif','https://static.exercisedb.dev/media/FWdVhcW.gif',NULL),
('fXfqg1E','weighted one hand pull up',NULL,'back','lats','{"biceps","forearms"}','other',NULL,'{"Step:1 Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Step:2 Hang from the bar with your arm fully extended and your body straight.","Step:3 Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.","Step:4 Continue pulling until your chin is above the bar.","Step:5 Lower your body back down to the starting position with control.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/fXfqg1E.gif','https://static.exercisedb.dev/media/fXfqg1E.gif',NULL),
('FxhcxUW','dumbbell seated one leg calf raise - hammer grip',NULL,'legs','calves','{"hamstrings","glutes"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Step:2 Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.","Step:3 Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.","Step:4 Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.","Step:5 Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch to the other leg."}','https://static.exercisedb.dev/media/FxhcxUW.gif','https://static.exercisedb.dev/media/FxhcxUW.gif',NULL),
('FY3UdNT','exercise ball on the wall calf raise (tennis ball between ankles)',NULL,'legs','calves','{"hamstrings","quadriceps"}','dumbbell',NULL,'{"Step:1 Stand facing a wall with your feet shoulder-width apart.","Step:2 Place an exercise ball between the wall and your lower back.","Step:3 Hold a dumbbell in each hand, with your arms extended by your sides.","Step:4 Place a tennis ball between your ankles.","Step:5 Raise your heels off the ground, lifting your body up onto your toes.","Step:6 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/FY3UdNT.gif','https://static.exercisedb.dev/media/FY3UdNT.gif',NULL),
('fY68AyX','dumbbell hammer curl on exercise ball',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Step:4 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/fY68AyX.gif','https://static.exercisedb.dev/media/fY68AyX.gif',NULL),
('fy7Tgy4','dumbbell alternate hammer preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Step:2 Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Step:3 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the recommended amount of repetitions."}','https://static.exercisedb.dev/media/fy7Tgy4.gif','https://static.exercisedb.dev/media/fy7Tgy4.gif',NULL),
('fZFZ704','weighted russian twist',NULL,'core','abs','{"obliques","lower back"}','other',NULL,'{"Step:1 Sit on the ground with your knees bent and your feet flat on the floor.","Step:2 Hold a weight or medicine ball with both hands in front of your chest.","Step:3 Lean back slightly, keeping your back straight and your core engaged.","Step:4 Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.","Step:5 Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/fZFZ704.gif','https://static.exercisedb.dev/media/fZFZ704.gif',NULL),
('G08RZcQ','cable curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Stand facing the cable machine with your feet shoulder-width apart.","Step:2 Grasp the cable attachment with an underhand grip, palms facing up.","Step:3 Keep your elbows close to your sides and your upper arms stationary.","Step:4 Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Step:5 Pause for a moment at the top of the movement, squeezing your biceps.","Step:6 Inhale and slowly lower the cable attachment back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/G08RZcQ.gif','https://static.exercisedb.dev/media/G08RZcQ.gif',NULL),
('G1qWW6M','macro style weighted one hand pull up',NULL,'back','lats','{"biceps","forearms"}','other',NULL,'{"Step:1 Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Step:2 Hang from the bar with your arm fully extended and your body straight. Perform with macro intensity.","Step:3 Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.","Step:4 Continue pulling until your chin is above the bar.","Step:5 Lower your body back down to the starting position with control.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/G1qWW6M.gif','https://static.exercisedb.dev/media/G1qWW6M.gif',NULL),
('g2oKspu','curl-up',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/g2oKspu.gif','https://static.exercisedb.dev/media/g2oKspu.gif',NULL),
('g376LuL','sled lying calf press',NULL,'legs','calves','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the sled machine to a comfortable weight.","Step:2 Sit on the sled machine with your back against the pad and your feet on the platform.","Step:3 Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.","Step:4 Push the platform away from you by extending your ankles, keeping your knees slightly bent.","Step:5 Continue pushing until your calves are fully contracted.","Step:6 Hold the contraction for a moment, then slowly lower the platform back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/g376LuL.gif','https://static.exercisedb.dev/media/g376LuL.gif',NULL),
('G61cXLk','cable kneeling rear delt row (with rope) (male)',NULL,'shoulders','delts','{"trapezius","rhomboids","biceps"}','cable',NULL,'{"Step:1 Attach a rope handle to a low cable pulley and kneel down facing the machine.","Step:2 Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.","Step:3 Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.","Step:4 Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.","Step:5 Slowly release the tension and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/G61cXLk.gif','https://static.exercisedb.dev/media/G61cXLk.gif',NULL),
('G70mEAJ','chin-ups (narrow parallel grip)',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.","Step:2 Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Step:3 Continue pulling until your chin is above the bar.","Step:4 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/G70mEAJ.gif','https://static.exercisedb.dev/media/G70mEAJ.gif',NULL),
('G7PXMlT','band vertical pallof press',NULL,'core','abs','{"obliques","glutes"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.","Step:2 Hold the band with both hands and step away from the anchor point, creating tension in the band.","Step:3 Position yourself perpendicular to the anchor point, with your side facing the band.","Step:4 Extend your arms straight out in front of you, keeping your hands at chest height.","Step:5 Engage your core and press the band away from your chest, fully extending your arms.","Step:6 Hold the position for a few seconds, then slowly bring the band back towards your chest.","Step:7 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/G7PXMlT.gif','https://static.exercisedb.dev/media/G7PXMlT.gif',NULL),
('G7xoEzr','barbell sitted alternate leg raise',NULL,'core','abs','{"hip flexors"}','barbell',NULL,'{"Step:1 Sit on a bench with your back straight and hold a barbell across your thighs.","Step:2 Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.","Step:3 Lower the raised leg back down and repeat with the other leg.","Step:4 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/G7xoEzr.gif','https://static.exercisedb.dev/media/G7xoEzr.gif',NULL),
('G8dXpNG','ez bar reverse grip bent over row',NULL,'back','upper back','{"biceps","forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.","Step:3 Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Step:4 Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/G8dXpNG.gif','https://static.exercisedb.dev/media/G8dXpNG.gif',NULL)
